// Field comparison for a published Meetup listing.
// The Meetup side is the last snapshot sent, which is what Meetup is still showing
// until someone edits the listing there. Pull replaces the club event from the live listing.

export type SyncFace = {
  title: string;
  description: string;
  starts_at: string;
  ends_at: string | null;
  venue_name: string | null;
  venue_address: string | null;
  image_url?: string | null;
};

export type SyncFieldKey = 'title' | 'starts' | 'ends' | 'venue' | 'address' | 'cover' | 'description';

export type SyncDiffRow = {
  key: SyncFieldKey;
  label: string;
  club: string | null;
  meetup: string | null;
};

const SNIPPET = 160;

function text(value: string | null | undefined): string {
  return (value ?? '').trim();
}

function sameText(a: string | null | undefined, b: string | null | undefined): boolean {
  return text(a) === text(b);
}

/** Minute precision. The screen shows hours and minutes, so a seconds-only save is not a visible difference. */
function sameTime(a: string | null | undefined, b: string | null | undefined): boolean {
  if (!text(a) && !text(b)) return true;
  if (!text(a) || !text(b)) return false;
  const left = Date.parse(a as string);
  const right = Date.parse(b as string);
  if (Number.isNaN(left) || Number.isNaN(right)) return text(a) === text(b);
  return Math.floor(left / 60000) === Math.floor(right / 60000);
}

/** Description with tags removed, so a Meetup HTML listing can sit next to club text. */
export function syncPlain(source: string | null | undefined): string {
  const raw = source ?? '';
  if (!raw.trim()) return '';
  const text = raw
    .replace(/<\s*br\s*\/?\s*>/gi, '\n')
    .replace(/<\s*\/\s*(p|div|h[1-6]|li)\s*>/gi, '\n')
    .replace(/<[^>]+>/g, ' ');
  return text.replace(/[ \t]+\n/g, '\n').replace(/\n{3,}/g, '\n\n').replace(/[ \t]{2,}/g, ' ').trim();
}

export function syncSnippet(source: string | null | undefined, max = SNIPPET): string {
  const one = syncPlain(source).replace(/\s+/g, ' ').trim();
  if (one.length <= max) return one;
  return `${one.slice(0, max - 1).trimEnd()}\u2026`;
}

/** Rows whose club value and sent Meetup value differ. Matching fields are left out. */
export function meetupSyncRows(club: SyncFace, meetup: SyncFace): SyncDiffRow[] {
  const rows: SyncDiffRow[] = [];
  if (!sameText(club.title, meetup.title)) {
    rows.push({ key: 'title', label: 'Title', club: text(club.title) || null, meetup: text(meetup.title) || null });
  }
  if (!sameTime(club.starts_at, meetup.starts_at)) {
    rows.push({ key: 'starts', label: 'Starts', club: text(club.starts_at) || null, meetup: text(meetup.starts_at) || null });
  }
  if (!sameTime(club.ends_at, meetup.ends_at)) {
    rows.push({ key: 'ends', label: 'Ends', club: club.ends_at, meetup: meetup.ends_at });
  }
  if (!sameText(club.venue_name, meetup.venue_name)) {
    rows.push({ key: 'venue', label: 'Venue', club: text(club.venue_name) || null, meetup: text(meetup.venue_name) || null });
  }
  if (!sameText(club.venue_address, meetup.venue_address)) {
    rows.push({ key: 'address', label: 'Address', club: text(club.venue_address) || null, meetup: text(meetup.venue_address) || null });
  }
  if (!sameText(club.image_url, meetup.image_url)) {
    rows.push({ key: 'cover', label: 'Cover', club: club.image_url ?? null, meetup: meetup.image_url ?? null });
  }
  if (syncPlain(club.description) !== syncPlain(meetup.description)) {
    rows.push({
      key: 'description',
      label: 'Description',
      club: syncSnippet(club.description) || null,
      meetup: syncSnippet(meetup.description) || null,
    });
  }
  return rows;
}
