// Shared bits for local platform events (list rows).
import { useCallback, useState } from 'react';
import { Image, LayoutChangeEvent, Linking, Platform, Pressable, Text, useWindowDimensions, View } from 'react-native';
import { router } from 'expo-router';
import { ListRow, styles, type Column } from './ui';
import { fmtWhen } from '../lib/format';
import { eventVisibility, eventVisibilityLabel } from '../lib/event-visibility';
import { publicPlaceLine, safeMeetingUrl, type ShownPlace } from '../lib/place';
import { clubListEndMs } from '../lib/event-relation';
import type { ClubEvent, PublicEvent } from '../lib/types';
import { PUBLIC_COVER_ASPECT } from '../lib/public-group';
import { colors, fonts, fs, radius, viewportWidth } from '../lib/theme';

// WHEN fits "Wed, Oct 28 at 7:30 PM" on one line.
const EVENT_COLS: Column[] = [{ label: 'Event', flex: 2 }, { label: 'When', width: 176 }];
// Measured list width: cover + ellipsized title + when + row chrome.
// Kept at the width that used to include a status column, so titles are not squeezed into a table earlier.
const EVENT_TABLE_MIN = 560;
// Used only before the list has been measured (window width, which includes page padding).
const EVENT_WINDOW_WIDE = 640;

/** Columns when the list is actually wide enough; stacked rows otherwise. */
export function useListColumns(wideColumns: Column[]) {
  const { width: windowWidth } = useWindowDimensions();
  const [listWidth, setListWidth] = useState<number | null>(null);
  const onLayout = useCallback((e: LayoutChangeEvent) => {
    const w = Math.round(e.nativeEvent.layout.width);
    if (w < 1) return;
    setListWidth((cur) => (cur === w ? cur : w));
  }, []);
  const guess = viewportWidth(windowWidth);
  const wide = listWidth != null ? listWidth >= EVENT_TABLE_MIN : guess >= EVENT_WINDOW_WIDE;
  return { columns: wide ? wideColumns : undefined, onLayout };
}

export function useEventListLayout() {
  return useListColumns(EVENT_COLS);
}
export const eventEndMs = clubListEndMs;
export const isLive = (e: { starts_at: string; ends_at: string | null }) => Date.parse(e.starts_at) <= Date.now() && Date.now() < eventEndMs(e);

const linkStyle = {
  color: colors.link,
  textDecorationLine: 'underline' as const,
  textDecorationColor: colors.link,
  ...(Platform.OS === 'web' ? { textDecoration: 'underline' } : {}),
};

/** Clickable zoom.us URL. The visible text is the URL. Other hosts render nothing. */
function ZoomUrl({ url }: { url: string }) {
  const web = Platform.OS === 'web';
  const anchor = web ? { href: url, hrefAttrs: { target: '_blank', rel: 'noopener noreferrer' } } : {};
  return (
    <Text selectable accessibilityRole="link"
      style={[styles.fieldValue, linkStyle, web ? { wordBreak: 'break-all', overflowWrap: 'anywhere' } as object : null]}
      {...anchor}
      onPress={() => { if (!web) Linking.openURL(url).catch(() => {}); }}>
      {url}
    </Text>
  );
}

/** Place field. A zoom.us URL is a normal link. A street stays plain text, with the link under it when the viewer may see one. */
export function PlaceValue({ place }: { place: ShownPlace }) {
  const href = safeMeetingUrl(place.href);
  const extra = href ? null : safeMeetingUrl(place.link);
  if (href) return <ZoomUrl url={href} />;
  const label = place.text.trim();
  if (!extra) return <Text selectable style={styles.fieldValue}>{label || '—'}</Text>;
  return (
    <View style={{ gap: 2, flexShrink: 1, minWidth: 0 }}>
      {label ? <Text selectable style={styles.fieldValue}>{label}</Text> : null}
      <ZoomUrl url={extra} />
    </View>
  );
}

/** Event cover image (hotlinked Meetup CDN URL). Renders nothing when there is no image. `fill` spans the parent. Default ratio is 1200 by 675; pass `aspectRatio` to center-crop a shorter band. */
export function EventCover({ url, width = 220, radius = 8, fill = false, aspectRatio, onError }: {
  url?: string | null; width?: number; radius?: number; fill?: boolean; aspectRatio?: number; onError?: () => void;
}) {
  if (!url) return null;
  if (fill) {
    return <Image source={{ uri: url }} accessibilityIgnoresInvertColors resizeMode="cover" onError={onError}
      style={{ width: '100%', aspectRatio: aspectRatio ?? PUBLIC_COVER_ASPECT, borderRadius: radius, backgroundColor: '#e8e4dc' }} />;
  }
  return <Image source={{ uri: url }} accessibilityIgnoresInvertColors resizeMode="cover" onError={onError}
    style={{ width, height: Math.round(width * 380 / 676), borderRadius: radius, backgroundColor: '#e8e4dc', flexShrink: 0 }} />;
}

function datePlate(iso: string) {
  const d = new Date(iso);
  if (Number.isNaN(d.getTime())) return null;
  return {
    month: d.toLocaleDateString(undefined, { month: 'short' }).toUpperCase(),
    day: String(d.getDate()),
  };
}

/** Public group event card: 1200×675 cover, then title, when, and the public place. */
export function PublicEventLinkCard({ event, onPress }: {
  event: Pick<PublicEvent, 'title' | 'starts_at' | 'venue_name' | 'venue_address' | 'image_url'>;
  onPress: () => void;
}) {
  const [broken, setBroken] = useState(false);
  const image = event.image_url && /^https:\/\//i.test(event.image_url) && !broken ? event.image_url : null;
  const plate = datePlate(event.starts_at);
  const place = publicPlaceLine(event.venue_name, event.venue_address);
  const where = place && place !== 'Place to be announced' ? place : null;
  return (
    <Pressable accessibilityRole="link" accessibilityLabel={`Open ${event.title}`} onPress={onPress}
      style={({ pressed, hovered }: { pressed: boolean; hovered?: boolean }) => [{
        flex: 1, backgroundColor: colors.card, borderWidth: 1, borderRadius: radius, overflow: 'hidden',
        borderColor: hovered ? colors.lineStrong : colors.line,
        opacity: pressed ? 0.92 : 1,
      }]}>
      {image ? (
        <Image source={{ uri: image }} accessibilityIgnoresInvertColors resizeMode="cover" onError={() => setBroken(true)}
          style={{ width: '100%', aspectRatio: PUBLIC_COVER_ASPECT, backgroundColor: colors.headerBg }} />
      ) : (
        <View style={{ width: '100%', aspectRatio: PUBLIC_COVER_ASPECT, alignItems: 'center', justifyContent: 'center', backgroundColor: colors.navy }}>
          {plate ? (
            <View style={{ alignItems: 'center' }}>
              <Text style={{ fontFamily: fonts.sansMedium, fontSize: fs(13), letterSpacing: 1.2, color: colors.gold }}>{plate.month}</Text>
              <Text style={{ fontFamily: fonts.serif, fontSize: fs(40), lineHeight: fs(44), color: '#fff' }}>{plate.day}</Text>
            </View>
          ) : null}
        </View>
      )}
      <View style={{ paddingHorizontal: 12, paddingTop: 10, paddingBottom: 12, gap: 4 }}>
        <Text numberOfLines={3} style={[styles.rowPrimary, { fontSize: fs(16), lineHeight: fs(21) }]}>{event.title}</Text>
        <Text numberOfLines={2} style={[styles.muted, { fontSize: fs(13) }]}>{fmtWhen(event.starts_at)}</Text>
        {where ? <Text numberOfLines={2} style={[styles.muted, { fontSize: fs(13) }]}>{where}</Text> : null}
      </View>
    </Pressable>
  );
}

type EventRelationBadge = 'Hosting' | 'Going';

/** Quiet relationship label. Same navy wash as the other status chips, sentence case. */
function RelationBadge({ label }: { label: EventRelationBadge }) {
  return (
    <View style={{ alignSelf: 'flex-start', backgroundColor: colors.navySoft, borderRadius: 999, paddingHorizontal: 8, paddingVertical: 1 }}>
      <Text style={{ fontFamily: fonts.sansMedium, fontSize: fs(11), color: colors.navy, letterSpacing: 0.2 }}>{label}</Text>
    </View>
  );
}

/** Title + subtitle cell with an optional small cover thumbnail. */
function EventTitleCell({ title, sub, image, badge }: {
  title: string; sub?: string | null; image?: string | null; badge?: EventRelationBadge | null;
}) {
  return (
    <View style={{ flexDirection: 'row', alignItems: 'flex-start', gap: 10, width: '100%', minWidth: 0, overflow: 'hidden' }}>
      <EventCover url={image} width={64} radius={6} />
      <View style={{ flex: 1, minWidth: 0, gap: 3 }}>
        <Text style={styles.rowPrimary} numberOfLines={1}>{title}</Text>
        {badge ? <RelationBadge label={badge} /> : null}
        {sub ? <Text style={[styles.muted, { fontSize: fs(12) }]} numberOfLines={1}>{sub}</Text> : null}
      </View>
    </View>);
}

export function EventListRow({ title, sub, image, when, badge, onPress, dim, accessibilityLabel, columns }: {
  title: string; sub?: string | null; image?: string | null; when: string; badge?: EventRelationBadge | null;
  onPress?: () => void; dim?: boolean; accessibilityLabel?: string; columns?: Column[];
}) {
  if (!columns?.length) {
    // Phone: cover | title + place + when stacked beside it. Nothing shares the cover's box.
    return (
      <ListRow onPress={onPress} dim={dim} accessibilityLabel={accessibilityLabel}>
        <View style={{ width: '100%', minWidth: 0, flexDirection: 'row', alignItems: 'flex-start', gap: 10 }}>
          <EventCover url={image} width={64} radius={6} />
          <View style={{ flexGrow: 1, flexShrink: 1, flexBasis: 0, minWidth: 0, gap: 3 }}>
            <Text numberOfLines={2} style={[styles.rowPrimary, { lineHeight: fs(20) }]}>{title}</Text>
            {badge ? <RelationBadge label={badge} /> : null}
            {sub ? <Text numberOfLines={1} style={[styles.muted, { fontSize: fs(12) }]}>{sub}</Text> : null}
            <Text numberOfLines={1} style={styles.rowCell}>{when}</Text>
          </View>
        </View>
      </ListRow>
    );
  }
  return (
    <ListRow columns={columns} onPress={onPress} dim={dim} accessibilityLabel={accessibilityLabel}
      cells={[<EventTitleCell title={title} image={image} sub={sub} badge={badge} />, when]} />);
}

export function EventRow({ e, past, mod, columns, badge }: {
  e: ClubEvent; past?: boolean; mod?: boolean; columns?: Column[]; badge?: EventRelationBadge | null;
}) {
  // City, or Online. Not the description: that text can carry a street or a Zoom line.
  const place = publicPlaceLine(e.venue_name, e.venue_locality);
  const kind = mod && eventVisibility(e.visibility) !== 'public' ? eventVisibilityLabel(e.visibility) : null;
  const sub = [place === 'Place to be announced' ? null : place, kind, mod && e.meetup_id ? 'On Meetup' : null].filter(Boolean).join(' · ') || null;
  return (
    <EventListRow title={e.title} image={e.image_url} sub={sub} when={fmtWhen(e.starts_at)} badge={badge} dim={past || e.archived}
      columns={columns} onPress={() => router.push(`/events/${e.id}`)}
      accessibilityLabel={`Open ${e.title}${badge ? `, ${badge}` : ''}`} />);
}
