// Identity helpers: @username is the unique handle; display_name is an optional friendly name.
import type { Profile } from './types';

export const RESERVED_USERNAMES = ['admin','administrator','moderator','mod','nycpprc','support','system','null','undefined',
  'me','root','staff','help','official','everyone','here','member','anonymous','deleted'];

type P = Pick<Profile, 'username' | 'display_name'> | null | undefined;
export const handle = (p: P) => (p?.username ? `@${p.username}` : 'Member');
/** Primary label: display name if set, else @username. */
export const primaryName = (p: P) => p?.display_name?.trim() || handle(p);
/** "Display Name · @user" or just "@user". */
export const fullName = (p: P) => (p?.display_name?.trim() ? `${p.display_name.trim()} · ${handle(p)}` : handle(p));

export function normalizeUsername(v: string) { return v.trim().replace(/^@+/, '').toLowerCase(); }
/** Returns an error message, or null if valid. Mirrors the DB check constraint. */
export function validateUsername(v: string): string | null {
  const u = normalizeUsername(v);
  if (u.length < 3 || u.length > 24) return 'Username must be 3–24 characters.';
  if (!/^[a-z0-9_]+$/.test(u)) return 'Use only lowercase letters, numbers, and underscores.';
  if (RESERVED_USERNAMES.includes(u)) return 'That username is reserved.';
  return null;
}
