// Realtime presence on one "lobby" channel, shared by web and the native app.
// A member is online while the app is in the foreground on either surface.
// Hiding the browser tab or backgrounding the phone untracks immediately, so
// they leave Online without waiting for a dead socket. The same user id is the
// presence key on every surface: phone and web are one Online row, and leaving
// one surface does not clear the other.
import { primaryName } from './names';
import { isAppForeground } from './chat-presence';
import React, { createContext, useCallback, useContext, useEffect, useRef, useState } from 'react';
import { AppState, Platform } from 'react-native';
import type { RealtimeChannel } from '@supabase/supabase-js';
import { supabase } from './supabase';
import { useSession } from './session';
import { useBiometric } from './biometric';
import { demoOnline, DEMO_ME } from './demo';
import { getProfile } from './api';
import type { OnlineUser } from './types';

type Ctx = { online: OnlineUser[]; setRoom: (roomId: string | null) => void };
const PresenceCtx = createContext<Ctx>({ online: [], setRoom: () => {} });

type Meta = { name: string; room_id: string | null };

function webVisibility(): 'visible' | 'hidden' | null {
  if (Platform.OS !== 'web' || typeof document === 'undefined') return null;
  return document.visibilityState === 'hidden' ? 'hidden' : 'visible';
}

function readForeground(): boolean {
  return isAppForeground({
    web: Platform.OS === 'web',
    appState: AppState.currentState,
    visibility: webVisibility(),
  });
}

export function PresenceProvider({ children }: { children: React.ReactNode }) {
  const { userId, demo } = useSession();
  const { revealed } = useBiometric();
  const [online, setOnline] = useState<OnlineUser[]>([]);
  const [demoRoom, setDemoRoom] = useState<string | null>(null);
  const chan = useRef<RealtimeChannel | null>(null);
  const meta = useRef<Meta>({ name: '', room_id: null });
  const foreground = useRef(true);

  const syncTrack = useCallback((ch: RealtimeChannel | null) => {
    if (!ch) return;
    if (foreground.current) void ch.track(meta.current);
    else void ch.untrack();
  }, []);

  useEffect(() => {
    // A locked session stays off the lobby until Face ID / fingerprint succeeds.
    if (demo || !userId || !revealed) return;
    let cancelled = false;
    foreground.current = readForeground();

    const onChange = () => {
      foreground.current = readForeground();
      syncTrack(chan.current);
    };
    const onPageHide = () => {
      foreground.current = false;
      void chan.current?.untrack();
    };
    const appSub = AppState.addEventListener('change', onChange);
    if (Platform.OS === 'web' && typeof document !== 'undefined') {
      document.addEventListener('visibilitychange', onChange);
      window.addEventListener('pagehide', onPageHide);
    }

    (async () => {
      try {
        const p = await getProfile(userId);
        meta.current.name = primaryName(p);
      } catch {
        meta.current.name = 'Member';
      }
      if (cancelled) return;
      // The socket can connect before the session token is applied, which drops
      // web joins. Set the token, then join the same lobby channel native uses.
      try {
        const { data } = await supabase.auth.getSession();
        if (data.session?.access_token) await supabase.realtime.setAuth(data.session.access_token);
      } catch { /* subscribe still uses whatever auth the client has */ }
      if (cancelled) return;
      const ch = supabase.channel('lobby', { config: { presence: { key: userId } } });
      ch.on('presence', { event: 'sync' }, () => {
        const state = ch.presenceState<Meta>();
        setOnline(Object.entries(state).map(([uid, metas]) => ({
          user_id: uid,
          name: metas[0]?.name ?? 'Member',
          room_id: metas[metas.length - 1]?.room_id ?? null,
        })));
      }).subscribe(async (status) => {
        if (status === 'SUBSCRIBED') syncTrack(ch);
      });
      chan.current = ch;
    })();

    return () => {
      cancelled = true;
      appSub.remove();
      if (Platform.OS === 'web' && typeof document !== 'undefined') {
        document.removeEventListener('visibilitychange', onChange);
        window.removeEventListener('pagehide', onPageHide);
      }
      const ch = chan.current;
      chan.current = null;
      if (ch) {
        void ch.untrack();
        supabase.removeChannel(ch);
      }
    };
  }, [userId, demo, revealed, syncTrack]);

  const setRoom = useCallback((roomId: string | null) => {
    if (demo) { setDemoRoom(roomId); return; }
    meta.current.room_id = roomId;
    // A backgrounded member keeps the room id for the next track, but does not
    // reappear in Online until the app is in the foreground again.
    if (foreground.current) void chan.current?.track(meta.current);
  }, [demo]);

  const value = demo
    ? { online: [...demoOnline, { user_id: DEMO_ME, name: 'Demo Member', room_id: demoRoom }], setRoom }
    : { online, setRoom };
  return <PresenceCtx.Provider value={value}>{children}</PresenceCtx.Provider>;
}
export const usePresence = () => useContext(PresenceCtx);
