// Pure rules for device notifications. Online is not an input.
// A banner is hidden only when this device is already showing that thread.

/** Same id as app.json extra.eas.projectId. Used when the runtime manifest omits it. */
export const EAS_PROJECT_ID = '84719083-d1d3-4710-a722-08336b2d809a';

/** IosAuthorizationStatus from expo-notifications. */
const IOS_NOT_DETERMINED = 0;
const IOS_DENIED = 1;
const IOS_AUTHORIZED = 2;
const IOS_PROVISIONAL = 3;
const IOS_EPHEMERAL = 4;

export function expoProjectId(input: { expoConfigProjectId?: string | null; easProjectId?: string | null }): string {
  const fromManifest = input.expoConfigProjectId?.trim() || input.easProjectId?.trim() || '';
  return fromManifest || EAS_PROJECT_ID;
}

export function isExpoPushToken(token: unknown): token is string {
  return typeof token === 'string'
    && (token.startsWith('ExponentPushToken[') || token.startsWith('ExpoPushToken['));
}

/**
 * Whether this device may register a token.
 * On iOS the root `status` field is not the source of truth; `ios.status` is.
 */
export function notificationsAllowed(input: {
  status?: string | null;
  granted?: boolean;
  iosStatus?: number | null;
}): boolean {
  const ios = input.iosStatus;
  if (ios === IOS_AUTHORIZED || ios === IOS_PROVISIONAL || ios === IOS_EPHEMERAL) return true;
  if (ios === IOS_NOT_DETERMINED || ios === IOS_DENIED) return false;
  return input.granted === true || input.status === 'granted';
}

/** Ask only while the choice is still open. A denial must not prompt on every foreground. */
export function shouldRequestNotificationPermission(input: {
  status?: string | null;
  iosStatus?: number | null;
}): boolean {
  if (notificationsAllowed(input)) return false;
  if (input.iosStatus === IOS_NOT_DETERMINED) return true;
  if (input.iosStatus == null && (input.status == null || input.status === 'undetermined')) return true;
  return false;
}

/** Foreground OS banner. The open thread stays quiet. Any other screen, including the app itself, does not. */
export function shouldPresentForegroundPush(input: { roomId: string; activeRoomId: string | null }): boolean {
  if (!input.roomId) return true;
  return input.roomId !== input.activeRoomId;
}
