// Pure helpers for event chats. The host rule itself lives in
// public.can_link_event_chat; these functions only shape the invite sheet.

export type InvitePreset = 'rsvp' | 'attending' | 'hosting';

export const INVITE_PRESETS: { id: InvitePreset; label: string; detail: string }[] = [
  { id: 'rsvp', label: 'RSVPs', detail: 'Meetup yes' },
  { id: 'attending', label: 'Attending', detail: 'App attend' },
  { id: 'hosting', label: 'Hosting', detail: 'Hosts' },
];

export type EventChatSummary = {
  room_id: string;
  title: string;
  created_by: string | null;
  member_count: number;
  created_at: string;
  event_count: number;
};

export type GroupChatSummary = EventChatSummary & { event_title: string | null };

export type EventChatTarget = {
  event_id: string;
  title: string;
  starts_at: string;
  series_id: string | null;
  series_title: string | null;
};

export type InvitePresetRow = { user_id: string; preset: InvitePreset };

export type EventChatLink = {
  event_id: string;
  title: string;
  starts_at: string;
  source: string;
  series_id: string | null;
};

/** People checked in the invite sheet. A pin keeps someone a preset would drop. An exclude drops someone a preset would add. */
export function selectedMemberIds(input: {
  presets: Record<InvitePreset, readonly string[]>;
  active: ReadonlySet<InvitePreset>;
  pinned: ReadonlySet<string>;
  excluded: ReadonlySet<string>;
}): string[] {
  const ids = new Set<string>();
  for (const name of input.active) {
    for (const id of input.presets[name] ?? []) ids.add(id);
  }
  for (const id of input.pinned) ids.add(id);
  for (const id of input.excluded) {
    if (!input.pinned.has(id)) ids.delete(id);
  }
  return [...ids];
}

export function pinMember(pinned: ReadonlySet<string>, excluded: ReadonlySet<string>, id: string, on: boolean): {
  pinned: Set<string>;
  excluded: Set<string>;
} {
  const nextPinned = new Set(pinned);
  const nextExcluded = new Set(excluded);
  if (on) {
    nextPinned.add(id);
    nextExcluded.delete(id);
  } else {
    nextPinned.delete(id);
    nextExcluded.add(id);
  }
  return { pinned: nextPinned, excluded: nextExcluded };
}

/**
 * Diff the event checkboxes against the links already stored.
 * Turning a series off upgrades any series-sourced session the host kept
 * so the detach does not drop it.
 */
export function eventLinkDelta(input: {
  links: readonly { event_id: string; source: string }[];
  selected: readonly string[];
  detachSeries: boolean;
}): { add: string[]; remove: string[] } {
  const selected = new Set(input.selected);
  const add = new Set<string>();
  const remove: string[] = [];
  const initial = new Set(input.links.map((link) => link.event_id));
  for (const id of selected) {
    const link = input.links.find((row) => row.event_id === id);
    if (!link) add.add(id);
    else if (input.detachSeries && link.source === 'series') add.add(id);
  }
  for (const id of initial) {
    if (!selected.has(id)) remove.push(id);
  }
  return { add: [...add], remove };
}

/** Events shown as included. The anchor stays on while creating. A series attach forces its sessions on. */
export function checkedEventIds(input: {
  anchorId: string;
  lockAnchor: boolean;
  manual: ReadonlySet<string>;
  attachSeries: boolean;
  seriesId: string | null;
  targets: readonly { event_id: string; series_id: string | null }[];
}): Set<string> {
  const ids = new Set(input.manual);
  if (input.lockAnchor) ids.add(input.anchorId);
  if (input.attachSeries && input.seriesId) {
    for (const row of input.targets) {
      if (row.series_id === input.seriesId) ids.add(row.event_id);
    }
  }
  return ids;
}

export function eventChatRowSubtitle(memberCount: number, eventCount: number): string {
  const people = memberCount === 1 ? '1 person' : `${memberCount} people`;
  if (eventCount > 1) return `${people} · ${eventCount} events`;
  return people;
}

export function groupChatSubtitle(memberCount: number, eventCount: number, eventTitle: string | null): string {
  const people = memberCount === 1 ? '1 person' : `${memberCount} people`;
  if (eventCount <= 0) return people;
  if (eventCount === 1) return eventTitle ? `${eventTitle} · ${people}` : people;
  return eventTitle ? `${eventTitle} · ${eventCount} events · ${people}` : `${eventCount} events · ${people}`;
}

/** Map create / link failures to a short line. */
export function explainEventChatError(message: string, fallback = 'Couldn’t save the chat.'): string {
  const m = message.toLowerCase();
  if (/create_event_chat|set_event_chat_events|event_chat_invite_presets|event_chat_link_targets|schema cache|could not find the function/.test(m)) {
    return 'Event chats aren’t available yet.';
  }
  if (m.includes('bad_title')) return 'Name the chat in 1–120 characters.';
  if (m.includes('no_series')) return 'This event isn’t part of a series.';
  if (m.includes('group_full')) return 'A chat can include up to 50 people.';
  if (m.includes('too_many_events')) return 'Link up to 100 events.';
  if (m.includes('user_not_found')) return 'One of the people you picked isn’t on the app.';
  if (m.includes('not_a_participant')) return 'You can’t change this chat.';
  if (m.includes('banned')) return 'Your account can’t start a chat right now.';
  if (m.includes('blocked') || m.includes('unavailable')) return 'One of the people you picked can’t be added.';
  if (m.includes('not_allowed') || m.includes('42501') || m.includes('permission denied')) return 'Only a host can add a chat to this event.';
  if (/syntax error|sqlstate|pgrst|jwt|stack/.test(m)) return fallback;
  const line = message.trim();
  if (line && line.length < 180) return line;
  return fallback;
}
