// Shared list chrome for Events and Groups: icon button, anchored menu, search row.
import React, { useCallback, useEffect, useRef, useState, type ComponentRef } from 'react';
import { Modal, Platform, Pressable, ScrollView, Text, TextInput, useWindowDimensions, View, type ViewStyle } from 'react-native';
import { Ionicons } from '@expo/vector-icons';
import { colors, fonts, fs, radius } from '../lib/theme';

const menuShadow: ViewStyle = Platform.OS === 'web'
  ? ({ boxShadow: '0 8px 24px rgba(18, 41, 75, 0.12)' } as ViewStyle)
  : { elevation: 8, shadowColor: '#12294b', shadowOpacity: 0.14, shadowRadius: 16, shadowOffset: { width: 0, height: 8 } };

export type MenuAnchor = { x: number; y: number; width: number; height: number };

function IconButton({ name, label, onPress, active }: {
  name: keyof typeof Ionicons.glyphMap; label: string; onPress: () => void; active?: boolean;
}) {
  return (
    <Pressable accessibilityRole="button" accessibilityLabel={label} onPress={onPress} hitSlop={6}
      style={({ pressed, hovered }: { pressed: boolean; hovered?: boolean }) => ({
        width: 36, height: 36, borderRadius: 6, alignItems: 'center', justifyContent: 'center',
        backgroundColor: active ? colors.navySoft : pressed || hovered ? colors.rowHover : 'transparent',
      })}>
      <Ionicons name={name} size={20} color={colors.navy} />
    </Pressable>
  );
}

export function Popover({ visible, anchor, align, width, onClose, children }: {
  visible: boolean; anchor: MenuAnchor | null; align: 'left' | 'right'; width: number; onClose: () => void; children: React.ReactNode;
}) {
  const { width: windowWidth, height: windowHeight } = useWindowDimensions();
  useEffect(() => {
    if (!visible || Platform.OS !== 'web') return;
    const onKey = (e: KeyboardEvent) => { if (e.key === 'Escape') onClose(); };
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  }, [visible, onClose]);
  if (!visible || !anchor) return null;
  const menuWidth = Math.min(width, Math.max(160, windowWidth - 16));
  const rawLeft = align === 'right' ? anchor.x + anchor.width - menuWidth : anchor.x;
  const left = Math.max(8, Math.min(rawLeft, windowWidth - menuWidth - 8));
  const top = Math.max(8, Math.min(anchor.y + anchor.height + 6, windowHeight - 24));
  return (
    <Modal transparent visible animationType="none" onRequestClose={onClose}>
      <View style={{ flex: 1 }}>
        <Pressable accessibilityLabel="Close menu" onPress={onClose} style={{ position: 'absolute', top: 0, left: 0, right: 0, bottom: 0 }} />
        <View accessibilityRole="menu" style={[{
          position: 'absolute', top, left, width: menuWidth, zIndex: 1,
          backgroundColor: '#fff', borderRadius: radius, borderWidth: 1, borderColor: colors.line, overflow: 'hidden',
        }, menuShadow]}>
          <ScrollView style={{ maxHeight: Math.max(180, windowHeight - top - 16) }} bounces={false}>{children}</ScrollView>
        </View>
      </View>
    </Modal>
  );
}

export function MenuCheckItem({ label, selected, onPress }: { label: string; selected: boolean; onPress: () => void }) {
  return (
    <Pressable accessibilityRole="menuitem" accessibilityState={{ selected }} onPress={onPress}
      style={({ pressed, hovered }: { pressed: boolean; hovered?: boolean }) => ({
        flexDirection: 'row', alignItems: 'center', justifyContent: 'space-between', gap: 12,
        paddingVertical: 11, paddingHorizontal: 14,
        backgroundColor: selected ? colors.navySoft : pressed || hovered ? colors.rowHover : '#fff',
      })}>
      <Text style={{ flexShrink: 1, fontFamily: selected ? fonts.sansMedium : fonts.sans, fontSize: fs(14), color: selected ? colors.navy : colors.ink }}>{label}</Text>
      {selected ? <Ionicons name="checkmark" size={16} color={colors.navy} /> : <View style={{ width: 16 }} />}
    </Pressable>
  );
}

export function MenuActionItem({ icon, label, disabled, onPress }: {
  icon: keyof typeof Ionicons.glyphMap; label: string; disabled?: boolean; onPress: () => void;
}) {
  return (
    <Pressable accessibilityRole="menuitem" disabled={disabled} onPress={onPress}
      style={({ pressed, hovered }: { pressed: boolean; hovered?: boolean }) => ({
        flexDirection: 'row', alignItems: 'center', gap: 8, paddingVertical: 11, paddingHorizontal: 14,
        opacity: disabled ? 0.5 : 1, backgroundColor: pressed || hovered ? colors.rowHover : '#fff',
      })}>
      <Ionicons name={icon} size={16} color={colors.navy} />
      <Text style={{ fontFamily: fonts.sansMedium, fontSize: fs(14), color: colors.navy }}>{label}</Text>
    </Pressable>
  );
}

export function measureAnchor(node: ComponentRef<typeof View> | null, fallback: MenuAnchor, show: (box: MenuAnchor) => void) {
  if (node && typeof node.measureInWindow === 'function') {
    node.measureInWindow((x, y, width, height) => show({ x, y, width, height }));
    return;
  }
  show(fallback);
}

/** View switcher, search, and the more-actions button. Menus render beside this, not inside it. */
export function ListToolbar({
  menuLabel, menuExpanded, onPressMenu, menuButtonRef,
  searchOpen, onToggleSearch, searchLabel, query, onQuery, searchPlaceholder, searchInputRef,
  showMore, moreExpanded, onPressMore, moreButtonRef,
}: {
  menuLabel: string;
  menuExpanded: boolean;
  onPressMenu: () => void;
  menuButtonRef: React.Ref<ComponentRef<typeof View>>;
  searchOpen: boolean;
  onToggleSearch: () => void;
  searchLabel: string;
  query: string;
  onQuery: (value: string) => void;
  searchPlaceholder: string;
  searchInputRef: React.Ref<ComponentRef<typeof TextInput>>;
  showMore: boolean;
  moreExpanded: boolean;
  onPressMore: () => void;
  moreButtonRef: React.Ref<ComponentRef<typeof View>>;
}) {
  return (
    <View style={{ gap: 8 }}>
      <View style={{ flexDirection: 'row', alignItems: 'center', gap: 4 }}>
        <View ref={menuButtonRef} collapsable={false} style={{ flexShrink: 1, minWidth: 0 }}>
          <Pressable accessibilityRole="button" accessibilityState={{ expanded: menuExpanded }}
            accessibilityLabel={`List view, ${menuLabel}`} onPress={onPressMenu}
            style={({ pressed }) => ({
              flexDirection: 'row', alignItems: 'center', gap: 8, maxWidth: '100%',
              backgroundColor: pressed ? colors.navyDark : colors.navy,
              borderRadius: 6, paddingVertical: 8, paddingHorizontal: 12,
            })}>
            <Text numberOfLines={1} style={{ flexShrink: 1, fontFamily: fonts.sansMedium, fontSize: fs(14), color: '#fff' }}>{menuLabel}</Text>
            <Ionicons name={menuExpanded ? 'chevron-up' : 'chevron-down'} size={16} color="#fff" />
          </Pressable>
        </View>
        <View style={{ flexDirection: 'row', alignItems: 'center', marginLeft: 'auto' }}>
          <IconButton name={searchOpen ? 'search' : 'search-outline'} label={searchOpen ? 'Close search' : searchLabel} active={searchOpen} onPress={onToggleSearch} />
          {showMore ? (
            <View ref={moreButtonRef} collapsable={false}>
              <IconButton name="ellipsis-horizontal" label="More actions" active={moreExpanded} onPress={onPressMore} />
            </View>
          ) : null}
        </View>
      </View>
      {searchOpen ? (
        <View style={{ flexDirection: 'row', alignItems: 'center', gap: 8, backgroundColor: '#fff', borderWidth: 1, borderColor: colors.lineStrong, borderRadius: 6, paddingHorizontal: 10 }}>
          <Ionicons name="search" size={15} color={colors.faint} />
          <TextInput ref={searchInputRef} value={query} onChangeText={onQuery} placeholder={searchPlaceholder} placeholderTextColor="#9aa1ad"
            autoCapitalize="none" autoCorrect={false} accessibilityLabel={searchLabel}
            style={[{ flex: 1, fontFamily: fonts.sans, fontSize: fs(14), color: colors.ink, paddingVertical: 8 }, Platform.OS === 'web' ? ({ outlineWidth: 0 } as object) : null]} />
          <Pressable accessibilityRole="button" accessibilityLabel="Close search" onPress={onToggleSearch} hitSlop={8}>
            <Ionicons name="close" size={16} color={colors.muted} />
          </Pressable>
        </View>
      ) : null}
    </View>
  );
}

/** Search row and the view / more menus shared by the Events and Groups lists. */
export function useListChrome() {
  const [query, setQuery] = useState('');
  const [searchOpen, setSearchOpen] = useState(false);
  const [menu, setMenu] = useState<'views' | 'more' | null>(null);
  const [anchor, setAnchor] = useState<MenuAnchor | null>(null);
  const viewBtn = useRef<ComponentRef<typeof View>>(null);
  const moreBtn = useRef<ComponentRef<typeof View>>(null);
  const searchRef = useRef<ComponentRef<typeof TextInput>>(null);
  const closeMenu = useCallback(() => setMenu(null), []);
  const openMenu = (which: 'views' | 'more') => {
    const node = (which === 'views' ? viewBtn : moreBtn).current;
    measureAnchor(node, { x: 16, y: 120, width: 220, height: 36 }, (box) => { setAnchor(box); setMenu(which); });
  };
  const toggleSearch = () => {
    setMenu(null);
    setSearchOpen((open) => {
      if (open) setQuery('');
      return !open;
    });
  };
  useEffect(() => { if (searchOpen) searchRef.current?.focus(); }, [searchOpen]);
  return { query, setQuery, searchOpen, menu, anchor, viewBtn, moreBtn, searchRef, closeMenu, openMenu, toggleSearch };
}
