// Shared confirm sheet. Event delete and group delete use the same shell.
import React, { useState } from 'react';
import { Modal, Pressable, Text, View } from 'react-native';
import { Ionicons } from '@expo/vector-icons';
import { Button, ErrorText, styles } from './ui';
import { colors, fs } from '../lib/theme';

export function IncludedRow({ label }: { label: string }) {
  return (
    <View accessibilityRole="checkbox" accessibilityState={{ checked: true, disabled: true }}
      style={{ flexDirection: 'row', alignItems: 'center', gap: 10 }}>
      <Ionicons name="checkbox" size={20} color={colors.navy} />
      <Text style={[styles.body, { flex: 1 }]}>{label}</Text>
      <Text style={[styles.muted, { fontSize: fs(12) }]}>Included</Text>
    </View>
  );
}

export function ConfirmSheet({ visible, title, body, children, error, busy, confirmTitle, onCancel, onConfirm }: {
  visible: boolean;
  title: string;
  body: string;
  children?: React.ReactNode;
  error: string | null;
  busy: boolean;
  confirmTitle: string;
  onCancel: () => void;
  onConfirm: () => void;
}) {
  const dismiss = () => { if (!busy) onCancel(); };
  return (
    <Modal transparent visible={visible} animationType="fade" onRequestClose={dismiss}>
      <Pressable style={{ flex: 1, backgroundColor: 'rgba(18,41,75,.35)', justifyContent: 'flex-end' }} onPress={dismiss}>
        <Pressable style={{ backgroundColor: colors.paper, padding: 20, borderTopLeftRadius: 18, borderTopRightRadius: 18, gap: 14, maxWidth: 640, width: '100%', alignSelf: 'center' }}>
          <Text style={styles.h2}>{title}</Text>
          <Text style={styles.body}>{body}</Text>
          {children}
          <ErrorText>{error}</ErrorText>
          <View style={{ flexDirection: 'row', gap: 10, justifyContent: 'flex-end' }}>
            <Button title="Cancel" variant="ghost" small disabled={busy} onPress={dismiss} />
            <Button title={confirmTitle} variant="destructive" small loading={busy} onPress={onConfirm} />
          </View>
        </Pressable>
      </Pressable>
    </Modal>
  );
}

/** Open / busy / error for an event or group delete sheet. Cancel does nothing while the delete is running. */
export function useConfirmDelete() {
  const [open, setOpen] = useState(false);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const ask = () => { setError(null); setOpen(true); };
  const cancel = () => { if (!busy) { setOpen(false); setError(null); } };
  const run = (task: () => Promise<void>) => {
    if (busy) return;
    setBusy(true);
    setError(null);
    task().then(() => { setOpen(false); }).catch((e: { message?: string }) => {
      setError(e?.message ?? null);
    }).finally(() => setBusy(false));
  };
  return { open, busy, error, ask, cancel, run };
}
