import { Platform } from 'react-native';
import AsyncStorage from '@react-native-async-storage/async-storage';
import * as Linking from 'expo-linking';
import * as WebBrowser from 'expo-web-browser';
import * as AppleAuthentication from 'expo-apple-authentication';
import * as Crypto from 'expo-crypto';
import { WEB_ORIGIN } from './config';
import { emailCodeDigits, emailCodeReady } from './email-code';
import { supabase } from './supabase';

WebBrowser.maybeCompleteAuthSession();

import Constants from 'expo-constants';

// Every value here must be allowlisted under Supabase Auth > URL Configuration > Redirect URLs,
// otherwise Supabase silently falls back to the Site URL and the email link opens the wrong host.
// Site URL should be https://gnosis.events/ (a person edits that in the Supabase dashboard).
// See docs/magic-link-redirects.md.
const RETURN_KEY = 'nycpprc-return-path';
const RETURN_MAX_AGE_MS = 30 * 60 * 1000;

/** Authenticated home when sign-in or session restore has no more specific path. */
export const SIGNED_IN_HOME = '/events';

// A return path the member asked for (deep link, attend, public event). The Android
// landing correction leaves this path alone. Not persisted: it only has to survive
// the navigation that consumes the stored return path.
let explicitLanding: string | null = null;

export function noteExplicitLanding(path: string | null) {
  explicitLanding = path;
}

export function peekExplicitLanding(): string | null {
  return explicitLanding;
}

/**
 * In-app path only, so a "return after sign-in" link cannot leave the app.
 * Accepts a single leading slash and the characters used in our routes.
 */
export function safeNextPath(raw: unknown): string | null {
  const value = Array.isArray(raw) ? raw[0] : raw;
  if (typeof value !== 'string' || value.length > 300) return null;
  let path = value.trim();
  try { path = decodeURIComponent(path); } catch { return null; }
  if (!/^\/(?!\/)[A-Za-z0-9/_-]{1,200}$/.test(path)) return null;
  if (path === '/sign-in' || path.startsWith('/sign-in/') || path === '/auth-callback' || path.startsWith('/auth-callback/')) return null;
  return path;
}

/** Remember where to send the member after sign-in. Shared across tabs (magic link opens a new one). */
export async function rememberReturnPath(raw: unknown): Promise<void> {
  const path = safeNextPath(raw);
  if (!path) return;
  const payload = JSON.stringify({ path, at: Date.now() });
  if (Platform.OS === 'web') {
    try { localStorage.setItem(RETURN_KEY, payload); } catch { /* private mode */ }
    return;
  }
  // AsyncStorage is not visible to a read started in the same turn. Callers that
  // read the return path next must await this, or Android still sees the old path.
  try { await AsyncStorage.setItem(RETURN_KEY, payload); } catch { /* ignore */ }
}

function parseReturn(raw: string | null): string | null {
  if (!raw) return null;
  try {
    const parsed = JSON.parse(raw) as { path?: unknown; at?: unknown };
    if (typeof parsed.at !== 'number' || Date.now() - parsed.at > RETURN_MAX_AGE_MS) return null;
    return safeNextPath(parsed.path);
  } catch { return null; }
}

async function loadReturnRaw(): Promise<string | null> {
  if (Platform.OS === 'web') {
    try { return localStorage.getItem(RETURN_KEY); } catch { return null; }
  }
  try { return await AsyncStorage.getItem(RETURN_KEY); } catch { return null; }
}

/** Read without clearing, so a cancelled navigation can try again. */
export async function readReturnPath(): Promise<string | null> {
  const path = parseReturn(await loadReturnRaw());
  if (!path) clearReturnPath();
  return path;
}

export function clearReturnPath() {
  if (Platform.OS === 'web') {
    try { localStorage.removeItem(RETURN_KEY); } catch { /* ignore */ }
    return;
  }
  AsyncStorage.removeItem(RETURN_KEY).catch(() => {});
}

export const NATIVE_SCHEME = 'gnosis-events';
export const NATIVE_REDIRECT = `${NATIVE_SCHEME}://auth-callback`;
/** Empty on the gnosis.events root build. `/app` only when this bundle was exported with APP_BASE_URL=/app. */
export const WEB_BASE_PATH = (process.env.EXPO_BASE_URL ?? '').replace(/\/$/, '');
// Optional https bridge for email clients that refuse custom schemes: set EXPO_PUBLIC_AUTH_BRIDGE=1
// for a native build and links go to https://gnosis.events/auth-callback?via=app, which hands off
// to gnosis-events://auth-callback (see app/auth-callback.tsx).

/** Where the magic link / OAuth returns: the same client that asked for it. */
export const redirectTo = (): string => {
  if (Platform.OS === 'web') {
    const origin = typeof window !== 'undefined' ? window.location.origin : WEB_ORIGIN;
    return `${origin}${WEB_BASE_PATH}/`; // e.g. https://gnosis.events/ or https://nycpprc.org/app/
  }
  // Expo Go only (dev): exp://<host>/--/auth-callback. Preview/production builds never use this.
  if (Constants.appOwnership === 'expo') return Linking.createURL('/auth-callback');
  if (process.env.EXPO_PUBLIC_AUTH_BRIDGE === '1') return `${WEB_ORIGIN}/auth-callback?via=app`;
  return NATIVE_REDIRECT; // ios + android dev/preview/production builds
};

export async function sendMagicLink(email: string) {
  const { error } = await supabase.auth.signInWithOtp({ email: email.trim().toLowerCase(), options: { emailRedirectTo: redirectTo(), shouldCreateUser: true } });
  if (error) throw error;
}

/**
 * Sign in with the code printed in the magic-link email.
 * The link in that same email still completes through the redirect.
 */
export async function verifyEmailCode(email: string, token: string) {
  const code = emailCodeDigits(token);
  if (!emailCodeReady(code)) throw new Error('Enter the code from the email.');
  const { data, error } = await supabase.auth.verifyOtp({
    email: email.trim().toLowerCase(),
    token: code,
    type: 'email',
  });
  if (error) throw error;
  if (!data.session?.user) throw new Error('Something went wrong');
  return data.session.user;
}

export async function signInWithGoogle() {
  if (Platform.OS === 'web') {
    await supabase.auth.signInWithOAuth({ provider: 'google', options: { redirectTo: redirectTo() } });
    return;
  }
  const { data, error } = await supabase.auth.signInWithOAuth({ provider: 'google', options: { redirectTo: redirectTo(), skipBrowserRedirect: true } });
  if (error || !data.url) throw error ?? new Error('No OAuth URL');
  const res = await WebBrowser.openAuthSessionAsync(data.url, redirectTo());
  if (res.type === 'success') await completeFromUrl(res.url);
}

export async function signInWithApple() {
  if (Platform.OS === 'ios') {
    try {
      const rawNonce = Crypto.randomUUID();
      const hashed = await Crypto.digestStringAsync(Crypto.CryptoDigestAlgorithm.SHA256, rawNonce);
      const cred = await AppleAuthentication.signInAsync({
        requestedScopes: [AppleAuthentication.AppleAuthenticationScope.FULL_NAME, AppleAuthentication.AppleAuthenticationScope.EMAIL],
        nonce: hashed,
      });
      if (!cred.identityToken) throw new Error('No identity token from Apple');
      const { error } = await supabase.auth.signInWithIdToken({ provider: 'apple', token: cred.identityToken, nonce: rawNonce });
      if (error) throw error;
      return;
    } catch (e: any) {
      // Closing the sheet is not a failure (same as dismissing Google's browser).
      if (e?.code === 'ERR_REQUEST_CANCELED') return;
      // Native module missing: browser OAuth below still starts Apple sign-in.
      if (e?.code !== 'ERR_UNAVAILABLE') throw e;
    }
  }
  // supabase-js assigns window.location only when document exists. On Android
  // (and any other non-browser client) the call returns the authorize URL and
  // stops, so the button does nothing and nothing throws. Open it the same way
  // as Google. On web, navigate ourselves so a missing URL is an on-screen error.
  await openOAuth('apple');
}

async function openOAuth(provider: 'apple') {
  const redirect = redirectTo();
  const { data, error } = await supabase.auth.signInWithOAuth({
    provider,
    options: { redirectTo: redirect, skipBrowserRedirect: true },
  });
  if (error || !data?.url) throw error ?? new Error('No OAuth URL');
  if (Platform.OS === 'web') {
    if (typeof window === 'undefined') throw new Error('No OAuth URL');
    window.location.assign(data.url);
    return;
  }
  const res = await WebBrowser.openAuthSessionAsync(data.url, redirect);
  if (res.type === 'success') {
    const ok = await completeFromUrl(res.url);
    if (!ok) throw new Error('Apple sign-in did not finish');
    return;
  }
  if (res.type === 'cancel' || res.type === 'dismiss') return;
  throw new Error('Apple sign-in could not be opened');
}

export type AuthParams = { code?: string | null; access_token?: string | null; refresh_token?: string | null; token_hash?: string | null; type?: string | null; error_description?: string | null; error?: string | null };

/** Pull auth params out of a callback URL (query and/or #fragment). */
export function authParamsFromUrl(url: string): AuthParams {
  const out: AuthParams = {};
  const q = url.indexOf('?'); const h = url.indexOf('#');
  const parts = [q >= 0 ? url.slice(q + 1, h > q ? h : undefined) : '', h >= 0 ? url.slice(h + 1) : ''];
  for (const part of parts) new URLSearchParams(part).forEach((v, k) => { (out as any)[k] = v; });
  return out;
}

/**
 * Completes sign-in from callback params. Throws on failure (callers decide what to show).
 * Returns true if a session now exists.
 */
export async function completeFromParams(p: AuthParams): Promise<boolean> {
  if (p.error || p.error_description) throw new Error(p.error_description || p.error || 'Sign-in failed');
  if (p.code) {
    const { error } = await supabase.auth.exchangeCodeForSession(p.code);
    if (error) {
      // Code may already have been exchanged (double delivery of the same link) - accept an existing session.
      const { data } = await supabase.auth.getSession();
      if (data.session) return true;
      throw error;
    }
  } else if (p.token_hash) {
    const { error } = await supabase.auth.verifyOtp({ token_hash: p.token_hash, type: (p.type as any) || 'email' });
    if (error) throw error;
  } else if (p.access_token && p.refresh_token) {
    const { error } = await supabase.auth.setSession({ access_token: p.access_token, refresh_token: p.refresh_token });
    if (error) throw error;
  } else {
    return false;
  }
  const { data } = await supabase.auth.getSession();
  return !!data.session;
}

// Handles PKCE (?code=), token_hash and implicit (#access_token=) callbacks.
export async function completeFromUrl(url: string): Promise<boolean> {
  if (!/[?#&](code|access_token|token_hash|error_description)=/.test(url)) return false;
  return completeFromParams(authParamsFromUrl(url));
}
