import React, { createContext, useCallback, useContext, useEffect, useMemo, useRef, useState } from 'react';
import { AppState, Platform } from 'react-native';
import { router, usePathname } from 'expo-router';
import { supabase } from './supabase';
import { isDemo } from './demo';
import {
  gateDecision,
  onAppState,
  reduceBootQueue,
  reduceRuntimeEvent,
  unlockFailureMessage,
  unlockMethod,
  unavailableReason,
  type AuthNotice,
  type BiometricKind,
  type GateDecision,
  type UnlockMethod,
} from './biometric-policy';
import {
  clearUnlockMarker,
  promptBiometric,
  readBiometricCapability,
  readBiometricEnabled,
  writeBiometricEnabled,
  writeUnlockMarker,
} from './biometric-native';

type Phase = 'open' | 'locked';

type LockState = {
  ready: boolean;
  phase: Phase;
  userId: string | null;
  enabled: boolean;
};

type Ctx = {
  decision: GateDecision;
  revealed: boolean;
  locked: boolean;
  holding: boolean;
  enabled: boolean;
  available: boolean;
  unavailableReason: string | null;
  method: UnlockMethod;
  busy: boolean;
  error: string | null;
  unlock: () => Promise<boolean>;
  setEnabled: (next: boolean) => Promise<void>;
  signInWithAccount: () => Promise<void>;
};

const webMethod = unlockMethod('web', []);

const BiometricCtx = createContext<Ctx>({
  decision: 'show-app',
  revealed: true,
  locked: false,
  holding: false,
  enabled: false,
  available: false,
  unavailableReason: null,
  method: webMethod,
  busy: false,
  error: null,
  unlock: async () => false,
  setEnabled: async () => {},
  signInWithAccount: async () => {},
});

export function BiometricProvider({ children }: { children: React.ReactNode }) {
  const demo = isDemo();
  const native = Platform.OS === 'ios' || Platform.OS === 'android';
  const pathname = usePathname();
  const [state, setState] = useState<LockState>({
    ready: !native || demo,
    phase: 'open',
    userId: null,
    enabled: false,
  });
  const [kinds, setKinds] = useState<BiometricKind[]>([]);
  const [hasHardware, setHasHardware] = useState(false);
  const [enrolled, setEnrolled] = useState(false);
  const [capReady, setCapReady] = useState(!native || demo);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const stateRef = useRef(state);
  const authenticating = useRef(false);
  const backgroundedAt = useRef<number | null>(null);
  const ticket = useRef(0);

  const commit = useCallback((next: LockState) => {
    stateRef.current = next;
    setState(next);
  }, []);

  useEffect(() => {
    if (!native) return;
    let live = true;
    readBiometricCapability().then((cap) => {
      if (!live) return;
      setHasHardware(cap.hasHardware);
      setEnrolled(cap.enrolled);
      setKinds(cap.kinds);
      setCapReady(true);
    }).catch(() => { if (live) setCapReady(true); });
    return () => { live = false; };
  }, [native]);

  useEffect(() => {
    if (!native || demo) return;
    let live = true;
    let bootstrapped = false;
    const queued: AuthNotice[] = [];

    const handleRuntime = (notice: AuthNotice) => {
      const cur = stateRef.current;
      const snap = reduceRuntimeEvent({ phase: cur.phase, userId: cur.userId }, notice);
      if (notice.event !== 'SIGNED_IN' && notice.event !== 'SIGNED_OUT') return;
      const mine = ++ticket.current;
      if (notice.event === 'SIGNED_OUT') {
        setError(null);
        commit({ ready: true, phase: 'open', userId: null, enabled: false });
        if (cur.userId) void clearUnlockMarker(cur.userId).catch(() => {});
        return;
      }
      // A real sign-in is the unlock before SecureStore returns, so the OAuth
      // callback can land on the app without flashing the lock. The preference
      // stays on for the next cold start.
      setError(null);
      commit({ ...cur, ready: true, phase: 'open', userId: snap.userId });
      const userId = snap.userId;
      void (async () => {
        const enabled = userId ? await readBiometricEnabled(userId).catch(() => false) : false;
        if (!live || ticket.current !== mine) return;
        if (userId && enabled) await writeUnlockMarker(userId).catch(() => {});
        if (!live || ticket.current !== mine) return;
        commit({ ready: true, phase: 'open', userId, enabled });
      })();
    };

    const { data: sub } = supabase.auth.onAuthStateChange((event, session) => {
      const notice = { event, userId: session?.user.id ?? null };
      if (!bootstrapped) {
        queued.push(notice);
        return;
      }
      handleRuntime(notice);
    });

    void (async () => {
      try {
        const { data } = await supabase.auth.getSession();
        if (!live) return;
        const restoredUserId = data.session?.user.id ?? null;
        const enabled = restoredUserId ? await readBiometricEnabled(restoredUserId).catch(() => false) : false;
        if (!live) return;
        const pending = queued.splice(0);
        bootstrapped = true;
        const snap = reduceBootQueue(restoredUserId, enabled, pending);
        const sameUser = snap.userId === restoredUserId;
        commit({
          ready: true,
          phase: snap.phase,
          userId: snap.userId,
          enabled: !!snap.userId && sameUser && enabled,
        });
        if (snap.userId && snap.phase === 'locked') await clearUnlockMarker(snap.userId).catch(() => {});
        if (snap.userId && !sameUser) {
          const flag = await readBiometricEnabled(snap.userId).catch(() => false);
          if (!live || stateRef.current.userId !== snap.userId) return;
          if (flag && stateRef.current.phase === 'open') await writeUnlockMarker(snap.userId).catch(() => {});
          if (!live || stateRef.current.userId !== snap.userId) return;
          commit({ ...stateRef.current, enabled: flag, ready: true });
        }
      } catch {
        if (!live) return;
        bootstrapped = true;
        commit({ ready: true, phase: 'open', userId: null, enabled: false });
      }
    })();

    return () => {
      live = false;
      sub.subscription.unsubscribe();
    };
  }, [native, demo, commit]);

  useEffect(() => {
    if (!native || demo) return;
    const sub = AppState.addEventListener('change', (next) => {
      const cur = stateRef.current;
      const decision = onAppState({
        next,
        now: Date.now(),
        authenticating: authenticating.current,
        backgroundedAt: backgroundedAt.current,
        enabled: cur.enabled,
        hasSession: !!cur.userId,
      });
      backgroundedAt.current = decision.backgroundedAt;
      if (!decision.relock || cur.phase === 'locked') return;
      setError(null);
      commit({ ...cur, phase: 'locked' });
      if (cur.userId) void clearUnlockMarker(cur.userId).catch(() => {});
    });
    return () => sub.remove();
  }, [native, demo, commit]);

  const method = useMemo(() => unlockMethod(Platform.OS, kinds), [kinds]);
  const available = native && hasHardware && enrolled;
  const reason = unavailableReason({ platform: Platform.OS, hasHardware, enrolled, kinds });

  const finishUnlock = useCallback(async (userId: string | null, enabled: boolean) => {
    if (userId && enabled) await writeUnlockMarker(userId).catch(() => {});
    const cur = stateRef.current;
    commit({ ...cur, ready: true, phase: 'open', userId: userId ?? cur.userId, enabled });
    setError(null);
  }, [commit]);

  const unlock = useCallback(async () => {
    const cur = stateRef.current;
    if (!native || !cur.userId || authenticating.current) return false;
    authenticating.current = true;
    setBusy(true);
    setError(null);
    try {
      const result = await promptBiometric(method.prompt);
      if (!result.ok) {
        setError(unlockFailureMessage(result.error, method.name));
        return false;
      }
      await finishUnlock(cur.userId, cur.enabled);
      return true;
    } catch {
      setError(unlockFailureMessage('unknown', method.name));
      return false;
    } finally {
      authenticating.current = false;
      setBusy(false);
    }
  }, [native, method.prompt, method.name, finishUnlock]);

  const setEnabled = useCallback(async (next: boolean) => {
    const cur = stateRef.current;
    if (!native || !cur.userId || authenticating.current) return;
    if (next && !available) return;
    // Biometrics removed: the prompt cannot run, so allow turning the flag off without it.
    if (!next && !available) {
      setBusy(true);
      setError(null);
      try {
        await writeBiometricEnabled(cur.userId, false);
        commit({ ...stateRef.current, enabled: false, phase: 'open', ready: true });
      } catch {
        setError('Couldn’t update this setting.');
      } finally {
        setBusy(false);
      }
      return;
    }
    authenticating.current = true;
    setBusy(true);
    setError(null);
    try {
      const result = await promptBiometric(method.prompt);
      if (!result.ok) {
        setError(unlockFailureMessage(result.error, method.name));
        return;
      }
      await writeBiometricEnabled(cur.userId, next);
      if (next) await writeUnlockMarker(cur.userId);
      commit({ ...stateRef.current, enabled: next, phase: 'open', ready: true });
      setError(null);
    } catch {
      setError('Couldn’t update this setting.');
    } finally {
      authenticating.current = false;
      setBusy(false);
    }
  }, [native, available, method.prompt, method.name, commit]);

  const signInWithAccount = useCallback(async () => {
    const id = stateRef.current.userId;
    authenticating.current = true;
    setBusy(true);
    setError(null);
    try {
      if (id) await clearUnlockMarker(id).catch(() => {});
      const { error: signOutError } = await supabase.auth.signOut();
      if (signOutError) throw signOutError;
      router.replace('/sign-in');
    } catch (e: any) {
      setError(e?.message || 'Couldn’t sign out. Try again.');
    } finally {
      authenticating.current = false;
      setBusy(false);
    }
  }, []);

  const decision = gateDecision({
    platform: Platform.OS,
    demo,
    // Wait for the sensor check too, so a stored preference cannot flash the app
    // and then lock, and a phone with biometrics removed is not trapped.
    preferenceKnown: state.ready && capReady,
    hasSession: !!state.userId,
    enabled: state.enabled && hasHardware && enrolled,
    unlocked: state.phase === 'open',
    pathname,
  });

  const value = useMemo<Ctx>(() => ({
    decision,
    revealed: decision === 'show-app',
    locked: decision === 'lock',
    holding: decision === 'hold',
    enabled: state.enabled,
    available,
    unavailableReason: reason,
    method,
    busy,
    error,
    unlock,
    setEnabled,
    signInWithAccount,
  }), [decision, state.enabled, available, reason, method, busy, error, unlock, setEnabled, signInWithAccount]);

  return <BiometricCtx.Provider value={value}>{children}</BiometricCtx.Provider>;
}

export function useBiometric() {
  return useContext(BiometricCtx);
}
