// Pure GA4 helpers. No React Native and no DOM, so tests can import this file.

/** gnosis.events web property. NYC PPRC and Gnosis Health use different IDs. */
export const GA_MEASUREMENT_ID_DEFAULT = 'G-0ZCS0F8102';

const GA_ID = /^G-[A-Z0-9]+$/;

/** Confirmed-at and last_sign_in_at are written in the same request on first success. */
export const NEW_ACCOUNT_MS = 60_000;

/** A magic-link or OAuth return is "this page load" for this long, plus clock skew. */
export const FRESH_SIGN_IN_MS = 10 * 60 * 1000;
export const CLOCK_SKEW_MS = 5 * 60 * 1000;

export type AuthStamp = {
  created_at?: string | null;
  last_sign_in_at?: string | null;
  email_confirmed_at?: string | null;
  confirmed_at?: string | null;
  app_metadata?: { provider?: string | null } | null;
  identities?: { provider?: string | null }[] | null;
};

/**
 * Measurement ID for the web shell. Invalid or empty values fall back to the
 * gnosis.events property so a production export still has a real ID.
 */
export function gaMeasurementId(raw?: string | null): string {
  const value = (raw ?? '').trim();
  return GA_ID.test(value) ? value : GA_MEASUREMENT_ID_DEFAULT;
}

export const GA_MEASUREMENT_ID = gaMeasurementId(process.env.EXPO_PUBLIC_GA_MEASUREMENT_ID);

function parsed(value: string | null | undefined): number | null {
  if (!value) return null;
  const n = Date.parse(value);
  return Number.isFinite(n) ? n : null;
}

function close(a: number | null, b: number | null, windowMs: number): boolean {
  if (a == null || b == null) return false;
  return Math.abs(a - b) < windowMs;
}

/**
 * True when this session is the account's first.
 * Magic links create the user when the email is sent and confirm them when the
 * link or code is used, so created_at can be minutes earlier than last_sign_in_at.
 * email_confirmed_at / confirmed_at is stamped on that first success and stays put.
 * OAuth usually stamps created_at and last_sign_in_at together. Unknown stamps
 * are not treated as new.
 */
export function isNewAccount(user: AuthStamp): boolean {
  const signedIn = parsed(user.last_sign_in_at);
  const confirmed = parsed(user.email_confirmed_at) ?? parsed(user.confirmed_at);
  if (close(signedIn, confirmed, NEW_ACCOUNT_MS)) return true;
  if (confirmed == null && close(signedIn, parsed(user.created_at), NEW_ACCOUNT_MS)) return true;
  return false;
}

const KNOWN_METHODS = new Set(['email', 'google', 'apple']);

/** GA4 method parameter. Provider id from Supabase, or email when it is missing. */
export function authMethod(user: AuthStamp): string {
  const provider = user.app_metadata?.provider || user.identities?.[0]?.provider || '';
  if (KNOWN_METHODS.has(provider)) return provider;
  return provider || 'email';
}

/** PKCE code, implicit token, or email token_hash in the query or hash. */
export function hrefHasAuthParams(href: string): boolean {
  return /[?#&](?:code|access_token|token_hash)=/.test(href);
}

/**
 * The sign-in timestamp belongs to this page load, not a session restored from storage.
 * Falls back to the confirm stamp when last_sign_in_at is absent.
 */
export function isFreshSignIn(user: AuthStamp, now = Date.now()): boolean {
  const signedIn = parsed(user.last_sign_in_at) ?? parsed(user.email_confirmed_at) ?? parsed(user.confirmed_at);
  if (signedIn == null) return false;
  const delta = now - signedIn;
  return delta >= -CLOCK_SKEW_MS && delta < FRESH_SIGN_IN_MS;
}
