// Named list views and the first club group. No React Native and no Supabase.
// The product is Gnosis Events (https://gnosis.events). This seed row is the NYCPPRC group, not the app.
// The Meetup urlname is the public slug. nycpprc.org is that group's marketing site, not the app.
// /g/reading-philosophy matches meetup.com/reading-philosophy/.
// The stored name stays the Meetup title. Do not rewrite it to the product name.

export const CLUB_GROUP_ID = 'a1000000-0000-4000-8000-000000000001';
export const CLUB_GROUP_SLUG = 'reading-philosophy';
/** Short label for the seeded reading club. The row's name stays the Meetup title. */
export const CLUB_GROUP_SHORT_NAME = 'NYCPPRC';
export const CLUB_GROUP_NAME = 'NYC Philosophy and Psychology Readers Community';
export const CLUB_GROUP_CITY = 'New York, NY';
export const CLUB_GROUP_ABOUT = 'We’re a community fostering friendship and insights by engaging in thoughtful discussions on significant concepts discovered from reading books and intellectual consumption. See: www.nycpprc.org';
export const CLUB_GROUP_COVER = 'https://secure.meetupstatic.com/photos/event/8/e/5/6/600_532596438.jpeg';
export const CLUB_GROUP_MEETUP = 'https://www.meetup.com/reading-philosophy/';

export const GROUP_VIEW_IDS = ['active', 'archived'] as const;
export type GroupViewId = (typeof GROUP_VIEW_IDS)[number];

export const GROUP_VIEWS: { id: GroupViewId; label: string }[] = [
  { id: 'active', label: 'All Groups' },
  { id: 'archived', label: 'Archived' },
];

export function groupViewLabel(id: GroupViewId): string {
  return GROUP_VIEWS.find((view) => view.id === id)?.label ?? 'All Groups';
}

/** New group is moderator-only, same gate as New event. */
export function groupScreenActions(mod: boolean): Array<'new'> {
  return mod ? ['new'] : [];
}

const SLUG = /^[a-z0-9]+(?:-[a-z0-9]+)*$/;

/** Lowercase hyphenated slug, 2–80 characters, or empty when nothing usable remains. */
export function normalizeGroupSlug(raw: string): string {
  return raw
    .trim()
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '')
    .slice(0, 80)
    .replace(/-+$/g, '');
}

export function isGroupSlug(slug: string): boolean {
  return slug.length >= 2 && slug.length <= 80 && SLUG.test(slug);
}

export function publicGroupPath(slug: string): string {
  return `/g/${encodeURIComponent(slug)}`;
}

type ListedGroup = {
  name: string;
  slug: string;
  description: string;
  locality?: string | null;
  archived: boolean;
};

/** Active or archived, name order. Search matches name, city, slug, and about. */
export function groupsForView<T extends ListedGroup>(
  groups: readonly T[],
  opts: { view: GroupViewId; query: string },
): T[] {
  const q = opts.query.trim().toLowerCase();
  return groups
    .filter((group) => {
      if (opts.view === 'archived' ? !group.archived : group.archived) return false;
      if (!q) return true;
      const hay = [group.name, group.locality ?? '', group.slug, group.description].join('\n').toLowerCase();
      return hay.includes(q);
    })
    .sort((a, b) => a.name.localeCompare(b.name) || a.slug.localeCompare(b.slug));
}
