// Shared message bubble for a direct message and the Socrates thread.
import React from 'react';
import { Platform, Pressable, Text, View } from 'react-native';
import { Avatar } from './ui';
import { colors, fonts, fs } from '../lib/theme';

export function TranscriptMessage({
  label, handleText, time, body, grouped, showTime = true, dim, mine, accent, avatarName, avatarPath, avatarUserId,
  onPressAvatar, avatarLabel, onLongPress, onMenu,
}: {
  label: string;
  handleText?: string | null;
  time: string;
  body: string;
  /** Same sender, within a few minutes of the previous line. Hides the avatar and name. */
  grouped: boolean;
  /** End of a burst. Shows the timestamp. */
  showTime?: boolean;
  dim?: boolean;
  mine?: boolean;
  /** Assistant line (Socrates): gold edge so it reads apart from a member. */
  accent?: boolean;
  avatarName: string;
  avatarPath?: string | null;
  avatarUserId?: string | null;
  onPressAvatar?: () => void;
  avatarLabel?: string;
  onLongPress?: () => void;
  onMenu?: () => void;
}) {
  const bubbleColor = mine ? colors.navy : '#fff';
  const textColor = mine ? '#fff' : colors.ink;
  const avatar = <Avatar name={avatarName} path={avatarPath} userId={avatarUserId} size={28} />;
  const bubble = (
    <View style={{ maxWidth: 520, minWidth: 0, flexShrink: 1, alignItems: mine ? 'flex-end' : 'flex-start' }}>
      {!mine && !grouped ? (
        <Text numberOfLines={1} style={{ fontFamily: fonts.sansMedium, fontSize: fs(12), color: colors.muted, marginBottom: 4, marginLeft: 4 }}>
          {label}{handleText ? ` · ${handleText}` : ''}
        </Text>
      ) : null}
      <View
        testID="chat-bubble"
        style={{
          backgroundColor: bubbleColor,
          borderWidth: mine ? 0 : 1,
          borderColor: colors.line,
          borderLeftWidth: accent ? 3 : mine ? 0 : 1,
          borderLeftColor: accent ? colors.gold : colors.line,
          borderRadius: 18,
          borderBottomRightRadius: mine ? 6 : 18,
          borderBottomLeftRadius: mine ? 18 : 6,
          paddingHorizontal: 14,
          paddingVertical: 9,
        }}
      >
        <Text selectable style={{ fontFamily: fonts.sans, fontSize: fs(15), lineHeight: fs(21), color: textColor }}>{body}</Text>
      </View>
      {showTime ? (
        <Text style={{ fontFamily: fonts.sans, fontSize: fs(11), color: colors.faint, marginTop: 4, marginHorizontal: 4 }}>{time}</Text>
      ) : null}
    </View>
  );
  const held = Platform.OS === 'web' || !onLongPress
    ? bubble
    : <Pressable onLongPress={onLongPress} delayLongPress={350}>{bubble}</Pressable>;
  return (
    <View style={{
      flexDirection: 'row',
      justifyContent: mine ? 'flex-end' : 'flex-start',
      alignItems: 'flex-start',
      gap: 8,
      marginTop: grouped ? 3 : 14,
      opacity: dim ? 0.5 : 1,
    }}>
      {mine ? null : (
        <View style={{ width: 28, marginTop: !grouped ? 18 : 0 }}>
          {grouped ? null : onPressAvatar
            ? <Pressable onPress={onPressAvatar} accessibilityLabel={avatarLabel}>{avatar}</Pressable>
            : avatar}
        </View>
      )}
      {mine && onMenu ? <MenuButton onPress={onMenu} /> : null}
      {held}
      {!mine && onMenu ? <MenuButton onPress={onMenu} /> : null}
    </View>
  );
}

function MenuButton({ onPress }: { onPress: () => void }) {
  return (
    <Pressable onPress={onPress} accessibilityRole="button" accessibilityLabel="Message options" hitSlop={10} style={{ paddingTop: 4, flexShrink: 0 }}>
      <Text style={{ color: colors.faint, fontSize: fs(18), lineHeight: fs(18) }}>⋯</Text>
    </Pressable>
  );
}
