export const fmtTime = (iso: string) => new Date(iso).toLocaleTimeString([], { hour: 'numeric', minute: '2-digit' });
/** Record-page date: "Oct 25, 2026, 7:00 PM". Empty values render as an em dash. */
export const fmtDate = (iso?: string | null) => (iso ? new Date(iso).toLocaleString([], { month: 'short', day: 'numeric', year: 'numeric', hour: 'numeric', minute: '2-digit' }) : '—');
export const fmtWhen = (iso: string) => new Date(iso).toLocaleString([], { weekday: 'short', month: 'short', day: 'numeric', hour: 'numeric', minute: '2-digit' });
/** No ends_at: the event counts as ended this long after starts_at. */
export const EVENT_END_FALLBACK_MS = 3 * 3600_000;

/** Event end time (ends_at, else starts_at + 3h). */
export function eventEndMs(r: { starts_at: string | null; ends_at: string | null }): number | null {
  if (r.ends_at) return Date.parse(r.ends_at);
  if (r.starts_at) return Date.parse(r.starts_at) + EVENT_END_FALLBACK_MS;
  return null;
}
export const eventEnded = (r: { starts_at: string | null; ends_at: string | null }) => {
  const e = eventEndMs(r); return e != null && Date.now() > e;
};

export const ATTENDANCE_ENDED = 'This event has ended.';
export const ATTENDANCE_STARTED = 'This event has already started.';

/**
 * Attend closes at ends_at. With no end time, it closes at starts_at.
 * This is stricter than eventEndMs, which keeps an open-ended event up for a few hours.
 * A missing or unreadable time stays closed so a row is not written by guesswork.
 */
export function attendanceClosed(
  e: { starts_at: string | null; ends_at: string | null },
  now = Date.now(),
): boolean {
  const closeAt = e.ends_at ?? e.starts_at;
  if (!closeAt) return true;
  const ms = Date.parse(closeAt);
  if (Number.isNaN(ms)) return true;
  return now >= ms;
}

/** Short reason for a closed Attend action. */
export function attendanceClosedMessage(e: { starts_at: string | null; ends_at: string | null }): string {
  if (!e.ends_at && e.starts_at && !Number.isNaN(Date.parse(e.starts_at))) return ATTENDANCE_STARTED;
  return ATTENDANCE_ENDED;
}

export function isAttendanceClosedMessage(message: string): boolean {
  return message.includes(ATTENDANCE_ENDED) || message.includes(ATTENDANCE_STARTED);
}
/** ISO → editable local "YYYY-MM-DD HH:mm" (inverse of parseLocal). */
export const toLocalInput = (iso: string | null) => {
  if (!iso) return '';
  const d = new Date(iso), p = (n: number) => String(n).padStart(2, '0');
  return `${d.getFullYear()}-${p(d.getMonth() + 1)}-${p(d.getDate())} ${p(d.getHours())}:${p(d.getMinutes())}`;
};
/** Local "YYYY-MM-DD HH:mm" (or any Date-parsable text) → ISO; empty → null. */
export const parseLocal = (s: string) => {
  if (!s.trim()) return null;
  const d = new Date(s.trim().replace(' ', 'T'));
  if (isNaN(+d)) throw new Error(`Couldn’t read the date “${s}”. Use YYYY-MM-DD HH:mm.`);
  return d.toISOString();
};
