// Moderator attendance views for Meetup RSVPs (RLS restricts meetup_rsvps to moderators).
import React, { useEffect, useMemo, useState } from 'react';
import { router } from 'expo-router';
import { EmptyState, ErrorText, ListRow, ListView, PersonFace, Segmented, StatusPill, type Column } from './ui';
import { listRsvpsForEvent, type MeetupRsvp } from '../lib/api';

export function RsvpPill({ r }: { r: Pick<MeetupRsvp, 'response' | 'attended'> }) {
  if (r.attended === 'ATTENDED') return <StatusPill label="Attended" tone="success" />;
  if (r.attended === 'NO_SHOW' || r.attended === 'ABSENT') return <StatusPill label="No-show" tone="danger" />;
  if (r.response === 'YES') return <StatusPill label="Going" tone="info" />;
  if (r.response === 'WAITLIST') return <StatusPill label="Waitlist" />;
  return <StatusPill label={(r.response ?? 'unknown').toLowerCase()} />;
}

type Filter = 'going' | 'attended' | 'all';
const COLS: Column[] = [{ label: 'Member', flex: 2 }, { label: 'Guests', width: 60, align: 'right' }, { label: 'Status', width: 110 }];

/** Who RSVP'd / attended one Meetup event. */
export function EventAttendance({ meetupEventId }: { meetupEventId: string }) {
  const [rows, setRows] = useState<MeetupRsvp[] | null>(null);
  const [err, setErr] = useState<string | null>(null);
  const [filter, setFilter] = useState<Filter>('going');
  useEffect(() => { listRsvpsForEvent(meetupEventId).then(setRows).catch((x) => setErr(x.message)); }, [meetupEventId]);
  const hasAttendance = (rows ?? []).some((r) => r.attended);
  const shown = useMemo(() => (rows ?? []).filter((r) =>
    filter === 'all' ? true : filter === 'attended' ? r.attended === 'ATTENDED' : r.response === 'YES'), [rows, filter]);
  return (
    <>
      <ErrorText>{err}</ErrorText>
      <Segmented<Filter> value={filter} onChange={setFilter} options={[
        { value: 'going', label: `Going${rows ? ` (${rows.filter((r) => r.response === 'YES').length})` : ''}` },
        ...(hasAttendance ? [{ value: 'attended' as Filter, label: `Attended (${rows!.filter((r) => r.attended === 'ATTENDED').length})` }] : []),
        { value: 'all', label: `All RSVPs${rows ? ` (${rows.length})` : ''}` },
      ]} />
      <ListView title="Attendance" count={rows ? shown.length : undefined} columns={COLS} loading={!rows && !err}
        empty={<EmptyState icon="people-outline" title="No RSVPs synced" body="Open Meetup members from Chat and run Sync to pull RSVPs and attendance." />}>
        {shown.map((r) => {
          const name = `${r.member_name ?? r.meetup_member_id}${r.is_host ? ' · host' : ''}`;
          return (
            <ListRow key={r.meetup_member_id} columns={COLS} onPress={() => router.push(`/meetup/member/${encodeURIComponent(r.meetup_member_id)}`)}
              cells={[
                <PersonFace name={r.member_name ?? '?'} label={name} uri={r.photo_url || null} fill />,
                r.guests || '—',
                <RsvpPill r={r} />,
              ]} />
          );
        })}
      </ListView>
    </>
  );
}
