import React from 'react';
import { Text, View, type ViewStyle } from 'react-native';
import { Card, styles } from './ui';
import { eventViewDetail, eventViewPlace, eventViewerLabel, type EventAnalyticsView } from '../lib/analytics-screen';
import { fmtDate } from '../lib/format';
import { colors, fs } from '../lib/theme';

const nf = new Intl.NumberFormat();

export function Stat({ label, value, note, style }: { label: string; value: number; note?: string; style?: ViewStyle }) {
  return (
    <Card style={style ?? { flexGrow: 1, flexBasis: 140 }}>
      <Text style={styles.fieldLabel}>{label}</Text>
      <Text style={[styles.h1, { marginTop: 4 }]}>{nf.format(value)}</Text>
      {note ? <Text style={[styles.muted, { fontSize: fs(12), marginTop: 2 }]}>{note}</Text> : null}
    </Card>
  );
}

/** Signed-out views, signed-in views, and app RSVPs. Notes differ for an event and a group. */
export function AnalyticsFunnel({ anonymous, authenticated, rsvps, anonymousNote, authenticatedNote, rsvpNote }: {
  anonymous: number; authenticated: number; rsvps: number;
  anonymousNote: string; authenticatedNote: string; rsvpNote: string;
}) {
  return (
    <View style={{ flexDirection: 'row', flexWrap: 'wrap', gap: 10 }}>
      <Stat label="Signed-out views" value={anonymous} note={anonymousNote} />
      <Stat label="Signed-in views" value={authenticated} note={authenticatedNote} />
      <Stat label="RSVPs" value={rsvps} note={rsvpNote} />
    </View>
  );
}

/** One view-log row. Group analytics also names the event. */
export function AnalyticsViewLog({ rows, showEventTitle }: { rows: EventAnalyticsView[]; showEventTitle?: boolean }) {
  if (!rows.length) return <Text style={styles.muted}>No views yet.</Text>;
  return (
    <>
      {rows.map((row) => {
        const place = eventViewPlace(row);
        const detail = eventViewDetail(row);
        return (
          <View key={row.id} style={{ paddingVertical: 10, borderBottomWidth: 1, borderBottomColor: colors.line }}>
            <View style={{ flexDirection: 'row', justifyContent: 'space-between', gap: 12 }}>
              <Text style={[styles.body, { flex: 1 }]} numberOfLines={1}>{eventViewerLabel(row.username)}</Text>
              <Text style={[styles.muted, { fontSize: fs(13) }]}>{fmtDate(row.at)}</Text>
            </View>
            {showEventTitle && row.eventTitle ? <Text style={[styles.muted, { fontSize: fs(13), marginTop: 2 }]} numberOfLines={1}>{row.eventTitle}</Text> : null}
            <Text style={[styles.muted, { fontSize: fs(13), marginTop: 2 }]}>{row.ip ?? '—'}</Text>
            <Text style={[styles.muted, { fontSize: fs(13) }]}>{place.ip ?? '—'}</Text>
            {place.device ? <Text style={[styles.muted, { fontSize: fs(13) }]}>Device {place.device}</Text> : null}
            {detail ? <Text style={[styles.muted, { fontSize: fs(13) }]}>{detail}</Text> : null}
          </View>
        );
      })}
    </>
  );
}

export function formatCount(value: number): string {
  return nf.format(value);
}
