// Public and unlisted event page. No attendee names. The place is a city or
// "Online" until an RSVP unlocks it. Private events offer Apply. Hidden events
// offer RSVP for the signed-in account only, with no plus-ones.
import { Text, View } from 'react-native';
import { Stack } from 'expo-router';
import { RichText } from './rich-text';
import { EventCover, PlaceValue, eventEndMs, isLive } from './events';
import { Button, FieldGrid, HighlightPanel, Page, SectionCard, StatusPill, styles } from './ui';
import { PRODUCT_NAME } from '../lib/config';
import type { EventJoinDetails } from '../lib/events';
import { attendanceClosed, attendanceClosedMessage, fmtDate } from '../lib/format';
import { allowsPlusOnes, eventVisibility, rsvpAction } from '../lib/event-visibility';
import { entitledAddress, entitledWhere, lockedDetailFields, lockedWhere, publicDescription } from '../lib/place';
import type { EventApplicationStatus, PublicEvent } from '../lib/types';

export function PublicEventScreen({
  event,
  userId,
  sessionLoading,
  going,
  join,
  application,
  onAttend,
  onApply,
  onLogin,
  onOpenInApp,
}: {
  event: PublicEvent;
  userId: string | null;
  sessionLoading: boolean;
  going: boolean;
  join: EventJoinDetails | null;
  application: EventApplicationStatus | null;
  onAttend: () => void;
  onApply: () => void;
  onLogin: () => void;
  onOpenInApp: () => void;
}) {
  const visibility = eventVisibility(event.visibility);
  const ended = eventEndMs(event) <= Date.now();
  const past = attendanceClosed(event);
  const unlocked = !!join;
  const action = rsvpAction({ visibility, past, going, application });
  const where = join
    ? entitledWhere(join.venue_name ?? event.venue_name, join.venue_address, join.online_meeting_url)
    : lockedWhere(event.venue_name, event.venue_address);
  const about = unlocked ? event.description : publicDescription(event.description);
  const attendLabel = visibility === 'hidden' ? 'RSVP' : 'Attend';
  const showOpen = !!userId && (visibility === 'public' || going || unlocked);
  const closedCopy = `${attendanceClosedMessage(event)}${userId ? '' : ' Sign in to open it in the members app.'}`;
  const intro = visibility === 'hidden'
    ? (unlocked
      ? 'You can see the exact place. Chat stays in the members app.'
      : past
        ? closedCopy
        : 'This page is unlisted. RSVP with your account to see the exact place. Plus-ones aren’t available.')
    : visibility === 'private'
      ? (unlocked
        ? 'You can see the exact place. Chat stays in the members app.'
        : past
          ? closedCopy
          : action === 'pending'
            ? 'Your application is with the host. People going aren’t listed on this page.'
            : application === 'declined'
              ? 'The host declined this application. You can apply again. People going aren’t listed on this page.'
              : 'Apply to attend. The host approves requests. People going aren’t listed on this page.')
      : (unlocked
        ? 'You can see the exact place. Chat stays in the members app.'
        : past
          ? closedCopy
          : userId
            ? 'Attend to see the exact place and the online join link. Chat stays in the members app.'
            : `Join ${PRODUCT_NAME} to attend. You’ll sign in or create an account, then the exact place opens in the app.`);
  const sectionTitle = action === 'apply' || action === 'pending'
    ? 'Apply'
    : userId
      ? (action === 'attend' ? attendLabel : 'Member')
      : past
        ? 'Join'
        : attendLabel;
  return (
    <Page>
      <Stack.Screen options={{ title: event.title }} />
      <HighlightPanel icon="calendar" media={event.image_url ? <EventCover url={event.image_url} width={220} /> : undefined}
        eyebrow={PRODUCT_NAME} title={event.title} subtitle={fmtDate(event.starts_at)}
        pills={<StatusPill label={ended ? 'Ended' : isLive(event) ? 'Live' : 'Upcoming'} tone={ended ? 'default' : isLive(event) ? 'success' : 'info'} />}
        fields={[['Starts', fmtDate(event.starts_at)], ['Ends', fmtDate(event.ends_at)], ['Where', <PlaceValue place={where} />]]} />
      <SectionCard title={sectionTitle}>
        <Text style={styles.body}>{intro}</Text>
        {visibility === 'hidden' && !allowsPlusOnes(visibility) && !unlocked && !past ? (
          <Text style={[styles.muted, { marginTop: 8 }]}>RSVP is just you.</Text>
        ) : null}
        {!sessionLoading ? (
          <View style={{ marginTop: 12, flexDirection: 'row', flexWrap: 'wrap', gap: 8, alignSelf: 'flex-start' }}>
            {action === 'apply' ? <Button icon="checkmark-outline" title={application === 'declined' ? 'Apply again' : 'Apply'} onPress={onApply} /> : null}
            {action === 'attend' ? <Button icon="checkmark-outline" title={attendLabel} onPress={onAttend} /> : null}
            {showOpen ? <Button variant={action === 'none' ? 'primary' : 'neutral'} icon="calendar-outline" title="Open in the app" onPress={onOpenInApp} /> : null}
            {!userId && action === 'none' ? <Button icon="log-in-outline" title="Log in" onPress={onLogin} /> : null}
            {!userId && action !== 'none' ? <Button variant="neutral" icon="log-in-outline" title="Log in" onPress={onLogin} /> : null}
          </View>
        ) : null}
      </SectionCard>
      <SectionCard title="Details">
        {join ? (
          <FieldGrid fields={[
            ['Starts', fmtDate(event.starts_at)],
            ['Ends', fmtDate(event.ends_at)],
            ['Venue', join.venue_name ?? event.venue_name ?? '—'],
            ['Address', <PlaceValue place={entitledAddress(join.venue_address, join.online_meeting_url)} />],
          ]} />
        ) : (
          <FieldGrid fields={lockedDetailFields(fmtDate(event.starts_at), fmtDate(event.ends_at), event.venue_name, event.venue_address)} />
        )}
      </SectionCard>
      {about ? <SectionCard title="About"><RichText source={about} /></SectionCard> : null}
    </Page>
  );
}
