// Foreground location for the Events Near me filter.
// Called only after the member turns Near me on. A denial or a missing
// native module returns a reason. It does not throw.
import { Platform } from 'react-native';
import type { GeoPoint } from './event-filters';

export type LocationRead =
  | { ok: true; point: GeoPoint }
  | { ok: false; reason: 'denied' | 'unavailable' };

const TIMEOUT_MS = 12_000;

function withTimeout<T>(work: Promise<T>, ms: number): Promise<T> {
  return new Promise((resolve, reject) => {
    const timer = setTimeout(() => reject(new Error('timeout')), ms);
    work.then(
      (value) => { clearTimeout(timer); resolve(value); },
      (err) => { clearTimeout(timer); reject(err); },
    );
  });
}

function pointOf(lat: unknown, lng: unknown): GeoPoint | null {
  if (typeof lat !== 'number' || typeof lng !== 'number') return null;
  if (!Number.isFinite(lat) || !Number.isFinite(lng)) return null;
  if (lat < -90 || lat > 90 || lng < -180 || lng > 180) return null;
  return { lat, lng };
}

function readWebLocation(): Promise<LocationRead> {
  return new Promise((resolve) => {
    const geo = typeof navigator !== 'undefined' ? navigator.geolocation : undefined;
    if (!geo) {
      resolve({ ok: false, reason: 'unavailable' });
      return;
    }
    // Start this inside the click. An awaited permissions query drops the browser prompt.
    geo.getCurrentPosition(
      (pos) => {
        const point = pointOf(pos.coords.latitude, pos.coords.longitude);
        resolve(point ? { ok: true, point } : { ok: false, reason: 'unavailable' });
      },
      (err) => resolve({ ok: false, reason: err?.code === 1 ? 'denied' : 'unavailable' }),
      { enableHighAccuracy: false, timeout: TIMEOUT_MS, maximumAge: 5 * 60_000 },
    );
  });
}

async function readNativeLocation(): Promise<LocationRead> {
  try {
    const Location = await import('expo-location');
    const existing = await Location.getForegroundPermissionsAsync();
    const perm = existing.status === 'granted' && existing.granted !== false
      ? existing
      : await Location.requestForegroundPermissionsAsync();
    if (perm.status !== 'granted' || perm.granted === false) {
      return { ok: false, reason: perm.status === 'denied' ? 'denied' : 'unavailable' };
    }
    const pos = await withTimeout(
      Location.getCurrentPositionAsync({ accuracy: Location.Accuracy.Balanced }),
      TIMEOUT_MS,
    );
    const point = pointOf(pos.coords.latitude, pos.coords.longitude);
    if (!point) return { ok: false, reason: 'unavailable' };
    return { ok: true, point };
  } catch {
    return { ok: false, reason: 'unavailable' };
  }
}

export function readDeviceLocation(): Promise<LocationRead> {
  if (Platform.OS === 'web') return readWebLocation();
  return readNativeLocation();
}

function peekWebLocation(): Promise<GeoPoint | null> {
  return new Promise((resolve) => {
    const geo = typeof navigator !== 'undefined' ? navigator.geolocation : undefined;
    const permissions = typeof navigator !== 'undefined' ? navigator.permissions : undefined;
    if (!geo || !permissions?.query) {
      resolve(null);
      return;
    }
    permissions.query({ name: 'geolocation' as PermissionName }).then((status) => {
      if (status.state !== 'granted') {
        resolve(null);
        return;
      }
      const timer = setTimeout(() => resolve(null), 800);
      geo.getCurrentPosition(
        (pos) => {
          clearTimeout(timer);
          resolve(pointOf(pos.coords.latitude, pos.coords.longitude));
        },
        () => { clearTimeout(timer); resolve(null); },
        { enableHighAccuracy: false, maximumAge: 10 * 60_000, timeout: 800 },
      );
    }, () => resolve(null));
  });
}

async function peekNativeLocation(): Promise<GeoPoint | null> {
  try {
    const Location = await import('expo-location');
    const existing = await Location.getForegroundPermissionsAsync();
    if (existing.status !== 'granted' || existing.granted === false) return null;
    const last = await Location.getLastKnownPositionAsync({ maxAge: 10 * 60_000 });
    return last ? pointOf(last.coords.latitude, last.coords.longitude) : null;
  } catch {
    return null;
  }
}

/**
 * A location the device already has. Does not request permission and does not
 * start a new GPS fix. Event analytics calls this; Near me uses readDeviceLocation.
 */
export function peekDeviceLocation(): Promise<GeoPoint | null> {
  if (Platform.OS === 'web') return peekWebLocation();
  return peekNativeLocation();
}
