import React, { createContext, useContext, useEffect, useState } from 'react';
import type { Session } from '@supabase/supabase-js';
import { supabase } from './supabase';
import { isDemo, DEMO_ME } from './demo';
import { amIModerator } from './api';
import { usePushRegistration } from './push';

type Ctx = { session: Session | null; userId: string | null; loading: boolean; isModerator: boolean; moderatorChecked: boolean; demo: boolean };
const SessionCtx = createContext<Ctx>({ session: null, userId: null, loading: true, isModerator: false, moderatorChecked: false, demo: false });

export function SessionProvider({ children }: { children: React.ReactNode }) {
  const demo = isDemo();
  const [session, setSession] = useState<Session | null>(null);
  const [loading, setLoading] = useState(!demo);
  const [isModerator, setMod] = useState(false);
  // User id the moderator RPC has resolved for. Stays stale across account
  // changes so a new sign-in is not treated as "checked" before the RPC returns.
  const [moderatorFor, setModeratorFor] = useState<string | null>(null);
  usePushRegistration(demo ? null : session?.user.id ?? null);

  useEffect(() => {
    if (demo) return;
    supabase.auth.getSession().then(({ data }) => { setSession(data.session); setLoading(false); });
    const { data: sub } = supabase.auth.onAuthStateChange((_e, s) => setSession(s));
    return () => sub.subscription.unsubscribe();
  }, [demo]);

  useEffect(() => {
    if (demo || !session) { setMod(false); setModeratorFor(null); return; }
    let live = true;
    const id = session.user.id;
    amIModerator().then((ok) => {
      if (!live) return;
      setMod(ok);
      setModeratorFor(id);
    }).catch(() => {
      if (!live) return;
      setMod(false);
      setModeratorFor(id);
    });
    return () => { live = false; };
  }, [session?.user.id, demo]);

  const userId = demo ? DEMO_ME : session?.user.id ?? null;
  const moderatorChecked = demo || !session || moderatorFor === session.user.id;
  // Ignore a moderator result from a previous account while the new check is in flight.
  const isModeratorLive = !!session && moderatorChecked && isModerator;
  return <SessionCtx.Provider value={{ session, userId, loading, isModerator: isModeratorLive, moderatorChecked, demo }}>{children}</SessionCtx.Provider>;
}
export const useSession = () => useContext(SessionCtx);
