// Meetup account link row for profiles. Own profile: Connect / Disconnect. Others: name + group-member badge.
// Organizers also get Connect your Meetup Pro network, one button per group they manage.
import React, { useEffect, useState } from 'react';
import { Linking as RNLinking, Platform, Pressable, Text, View } from 'react-native';
import * as Linking from 'expo-linking';
import * as WebBrowser from 'expo-web-browser';
import { Button, styles } from './ui';
import { colors, fonts, fs } from '../lib/theme';
import { disconnectMeetup, listMyMeetupConnections, startMeetupLink } from '../lib/api';
import type { MeetupProGroup } from '../lib/meetup-url';
import type { Profile } from '../lib/types';

const MEETUP_RED = '#e0393e';

function meetupReturnTo() {
  return Platform.OS === 'web'
    ? `${window.location.origin}${process.env.EXPO_BASE_URL ?? ''}/profile`
    : Linking.createURL('/profile');
}

async function openMeetupAuth(url: string | null, returnTo: string, onChange: () => void) {
  if (!url) { onChange(); return; }
  if (Platform.OS === 'web') { window.location.href = url; return; }
  await WebBrowser.openAuthSessionAsync(url, returnTo);
  onChange();
}

export function MeetupBadge({ p }: { p: Profile }) {
  if (!p.meetup_name) return null;
  return (
    <Pressable onPress={() => p.meetup_profile_url && RNLinking.openURL(p.meetup_profile_url)} accessibilityRole="link"
      style={{ flexDirection: 'row', alignItems: 'center', gap: 8, alignSelf: 'flex-start' }}>
      <Text style={[styles.muted, { fontSize: fs(14) }]}>
        <Text style={{ color: MEETUP_RED, fontFamily: fonts.sansMedium }}>Meetup</Text>  {p.meetup_name}
      </Text>
      {p.meetup_is_member ? <Text style={{ fontFamily: fonts.sansMedium, fontSize: fs(12), color: colors.online }}>✓ Member</Text> : null}
    </Pressable>
  );
}

export function MeetupConnect({ p, onChange, note }: { p: Profile; onChange: () => void; note?: string | null }) {
  const [busy, setBusy] = useState(false);
  const [err, setErr] = useState<string | null>(null);

  const connect = async () => {
    setBusy(true); setErr(null);
    try {
      const returnTo = meetupReturnTo();
      const url = await startMeetupLink(returnTo);
      await openMeetupAuth(url, returnTo, onChange);
    } catch (e: any) { setErr(e.message); } finally { setBusy(false); }
  };

  if (p.meetup_name) {
    return (
      <View style={{ alignItems: 'flex-start', gap: 8 }}>
        <MeetupBadge p={p} />
        <Button title="Disconnect Meetup" variant="danger" small loading={busy}
          onPress={async () => { setBusy(true); try { await disconnectMeetup(); onChange(); } catch (e: any) { setErr(e.message); } finally { setBusy(false); } }} />
        {note ? <Text style={[styles.muted, { fontSize: fs(13) }]}>{note}</Text> : null}
        {err ? <Text style={[styles.muted, { color: colors.danger }]}>{err}</Text> : null}
      </View>
    );
  }
  return (
    <View style={{ gap: 6 }}>
      <Button title="Connect Meetup" icon="link-outline" variant="neutral" style={{ alignSelf: 'flex-start' }} onPress={connect} loading={busy} />
      {err ? <Text style={[styles.muted, { color: colors.danger, textAlign: 'center' }]}>{err}</Text> : null}
    </View>
  );
}

/** Organizer Meetup Pro link. Pass the groups they manage; each urlname is stored on the OAuth state. */
export function MeetupProConnect({ groups, onChange }: { groups: MeetupProGroup[]; onChange?: () => void }) {
  const [busy, setBusy] = useState<string | null>(null);
  const [err, setErr] = useState<string | null>(null);
  const [linked, setLinked] = useState<string[]>([]);
  const [loaded, setLoaded] = useState(false);
  const key = groups.map((g) => g.urlname).join(',');

  const refresh = async () => {
    const rows = await listMyMeetupConnections();
    setLinked(rows.map((r) => r.group_urlname));
    setLoaded(true);
  };
  useEffect(() => {
    let live = true;
    listMyMeetupConnections()
      .then((rows) => { if (live) { setLinked(rows.map((r) => r.group_urlname)); setLoaded(true); } })
      .catch(() => { if (live) setLoaded(true); });
    return () => { live = false; };
  }, [key]);

  if (!groups.length || !loaded) return null;

  const connect = async (urlname: string) => {
    setBusy(urlname); setErr(null);
    try {
      const returnTo = meetupReturnTo();
      const url = await startMeetupLink(returnTo, urlname);
      await openMeetupAuth(url, returnTo, () => { onChange?.(); void refresh(); });
    } catch (e: any) { setErr(e.message); } finally { setBusy(null); }
  };
  const disconnect = async (urlname: string) => {
    setBusy(urlname); setErr(null);
    try {
      await disconnectMeetup(urlname);
      await refresh();
      onChange?.();
    } catch (e: any) { setErr(e.message); } finally { setBusy(null); }
  };

  return (
    <View style={{ gap: 10, alignItems: 'flex-start' }}>
      <Text style={[styles.muted, { fontSize: fs(13) }]}>
        {groups.length === 1
          ? `Uses your Meetup Pro organizer account for ${groups[0].name}. Disconnecting here leaves your member link alone.`
          : 'Choose a Meetup group you organize. Disconnecting one group leaves your member link and your other groups alone.'}
      </Text>
      {groups.map((g) => {
        const on = linked.includes(g.urlname);
        return (
          <View key={g.urlname} style={{ gap: 4, alignItems: 'flex-start' }}>
            {groups.length > 1 ? <Text style={[styles.fieldLabel]}>{g.name}</Text> : null}
            {on ? (
              <>
                <Text style={[styles.muted, { fontSize: fs(13) }]}>Meetup Pro connected{groups.length > 1 ? '' : ` for ${g.name}`}.</Text>
                <Button title="Disconnect Meetup Pro" variant="danger" small loading={busy === g.urlname} onPress={() => disconnect(g.urlname)} />
              </>
            ) : (
              <Button title="Connect your Meetup Pro network" icon="link-outline" variant="neutral" style={{ alignSelf: 'flex-start' }}
                loading={busy === g.urlname} onPress={() => connect(g.urlname)} />
            )}
          </View>
        );
      })}
      {err ? <Text style={[styles.muted, { color: colors.danger }]}>{err}</Text> : null}
    </View>
  );
}
