// Shared rules for "online" and for DM alerts. Web and native use the same lobby
// channel; a hidden tab or a backgrounded phone is not online. Socrates is not
// a Realtime heartbeat: when the contact is shown, the roster treats them as online.

export function isAppForeground(input: {
  web: boolean;
  appState: string | null | undefined;
  /** document.visibilityState. Null on native and in tests that only set appState. */
  visibility: 'visible' | 'hidden' | null;
}): boolean {
  const appState = input.appState ?? '';
  if (input.web && input.visibility === 'hidden') return false;
  if (input.web && input.visibility === 'visible') return true;
  if (input.web) return appState === 'active';
  // `inactive` is a control-center or app-switcher peek. `background` means they left.
  return appState === 'active' || appState === 'inactive';
}

/** True when this insert should ring. Online does not mute. The open thread does. */
export function shouldAlertForMessage(input: {
  senderId: string;
  selfId: string | null;
  roomId: string;
  activeRoomId: string | null;
  directRoom: boolean;
  /** An event group chat this member belongs to. Shared rooms stay quiet. */
  memberRoom?: boolean;
  removed: boolean;
}): boolean {
  if (input.removed) return false;
  if (!input.selfId || !input.senderId || input.senderId === input.selfId) return false;
  if (!input.directRoom && !input.memberRoom) return false;
  if (input.activeRoomId && input.roomId === input.activeRoomId) return false;
  return true;
}

/** One line, cut to `limit` characters. Matches the push body (140, with an ellipsis). */
export function alertPreview(body: string, limit = 140): string {
  const line = body.replace(/\s+/g, ' ').trim();
  if (line.length <= limit) return line;
  if (limit < 2) return line.slice(0, limit);
  return `${line.slice(0, limit - 1)}…`;
}

/** Stable id for the Socrates roster row. Not a user id, so it cannot open a DM. */
export const SOCRATES_CONTACT_ID = 'socrates';

export function includeSocrates(show: boolean, query: string, name: string, subtitle: string): boolean {
  if (!show) return false;
  const needle = query.trim().toLowerCase();
  if (!needle) return true;
  return `${name} ${subtitle}`.toLowerCase().includes(needle);
}

/**
 * In-app DM alerts subscribe to message inserts. Realtime applies RLS, so an
 * anonymous join receives nothing and does not start receiving later.
 * Wait until the session token exists, then set it on the socket before subscribe.
 */
export function canListenForDmAlerts(input: {
  demo: boolean;
  userId: string | null;
  accessToken: string | null;
}): boolean {
  return !input.demo && !!input.userId && !!input.accessToken;
}
