// Web-only GA4 events. Native imports this too; every call returns without touching gtag.
// The measurement ID is configured by the snippet in public/index.html. This file only
// sends events when that snippet has defined window.gtag (gnosis.events).
import { useEffect, useRef } from 'react';
import { Platform } from 'react-native';
import { authMethod, hrefHasAuthParams, isFreshSignIn, isNewAccount, type AuthStamp } from './ga';
import { supabase, WEB_BOOT_HREF } from './supabase';

type Gtag = (...args: unknown[]) => void;

type GaWindow = Window & { gtag?: Gtag };

function sendGa(name: 'sign_up' | 'login' | 'page_view', params: Record<string, string>) {
  if (Platform.OS !== 'web' || typeof window === 'undefined') return;
  const gtag = (window as GaWindow).gtag;
  if (typeof gtag !== 'function') return;
  gtag('event', name, params);
}

/**
 * sign_up when the account was just created, login for a later session.
 * Same user and same sign-in stamp are sent once per tab.
 */
export function reportWebAuth(user: AuthStamp & { id: string }) {
  if (Platform.OS !== 'web' || typeof window === 'undefined') return;
  const name = isNewAccount(user) ? 'sign_up' : 'login';
  const stamp = user.last_sign_in_at || user.email_confirmed_at || user.confirmed_at || user.created_at || 'unknown';
  const key = `gnosis-ga:${name}:${user.id}:${stamp}`;
  try {
    if (window.sessionStorage.getItem(key)) return;
    window.sessionStorage.setItem(key, '1');
  } catch {
    // Private mode can throw. Still send.
  }
  sendGa(name, { method: authMethod(user) });
}

export function reportWebPageView(path: string) {
  if (Platform.OS !== 'web' || typeof window === 'undefined' || !path) return;
  sendGa('page_view', {
    page_path: path,
    page_location: window.location.href,
    page_title: document.title,
  });
}

/**
 * Magic link and OAuth return to the site with a code. supabase-js may finish
 * that exchange before React subscribes, so also read the session once.
 * A stored session with no auth params is not a sign-up or a login.
 */
export function watchWebAuth(): () => void {
  if (Platform.OS !== 'web' || typeof window === 'undefined') return () => {};
  if (!hrefHasAuthParams(WEB_BOOT_HREF)) return () => {};
  let live = true;
  const reportIfFresh = (user: (AuthStamp & { id: string }) | null | undefined) => {
    if (!live || !user?.id) return;
    if (!isFreshSignIn(user)) return;
    reportWebAuth(user);
  };
  const { data: sub } = supabase.auth.onAuthStateChange((event, session) => {
    if (event !== 'SIGNED_IN') return;
    reportIfFresh(session?.user);
  });
  supabase.auth.getSession().then(({ data }) => {
    reportIfFresh(data.session?.user);
  }).catch(() => {});
  return () => {
    live = false;
    sub.subscription.unsubscribe();
  };
}

/** Initial page_view comes from the HTML snippet. Later in-app routes are sent here. */
export function useWebAnalytics(pathname: string | null | undefined) {
  const first = useRef(true);
  const last = useRef<string | null>(null);
  useEffect(() => watchWebAuth(), []);
  useEffect(() => {
    if (Platform.OS !== 'web' || !pathname) return;
    if (first.current) {
      first.current = false;
      last.current = pathname;
      return;
    }
    if (last.current === pathname) return;
    last.current = pathname;
    reportWebPageView(pathname);
  }, [pathname]);
}
