import 'react-native-url-polyfill/auto';
import { Platform } from 'react-native';
import AsyncStorage from '@react-native-async-storage/async-storage';
import { createClient } from '@supabase/supabase-js';
import { SUPABASE_URL, SUPABASE_PUBLISHABLE_KEY } from './config';

/**
 * Address bar at module load, before supabase-js strips a PKCE code from the URL.
 * Empty on native. GA uses this to tell a magic-link or OAuth return from a restored session.
 */
export const WEB_BOOT_HREF =
  Platform.OS === 'web' && typeof window !== 'undefined' ? window.location.href : '';

export const supabase = createClient(SUPABASE_URL, SUPABASE_PUBLISHABLE_KEY, {
  auth: {
    storage: Platform.OS === 'web' ? undefined : AsyncStorage,
    autoRefreshToken: true,
    persistSession: true,
    detectSessionInUrl: Platform.OS === 'web',
    flowType: 'pkce',
  },
});

/** Signed-in account. Creates send this as owner_id. */
export async function signedInUserId(): Promise<string> {
  const { data } = await supabase.auth.getSession();
  const id = data.session?.user.id;
  if (!id) throw new Error('You need to be signed in.');
  return id;
}
