// Club vs last sent Meetup listing. Only fields that differ are passed in.
import React from 'react';
import { Text, useWindowDimensions, View } from 'react-native';
import { Ionicons } from '@expo/vector-icons';
import { EventCover } from './events';
import { styles } from './ui';
import { fmtDate } from '../lib/format';
import type { SyncDiffRow, SyncFieldKey } from '../lib/meetup-sync';
import { colors, fs } from '../lib/theme';

const ICONS: Record<SyncFieldKey, keyof typeof Ionicons.glyphMap> = {
  title: 'text-outline',
  starts: 'time-outline',
  ends: 'time-outline',
  venue: 'business-outline',
  address: 'location-outline',
  cover: 'image-outline',
  description: 'document-text-outline',
};

const EMPTY = '\u2014';

function cellText(row: SyncDiffRow, side: 'club' | 'meetup'): string {
  const raw = side === 'club' ? row.club : row.meetup;
  if (row.key === 'cover') return raw ? 'image' : 'none';
  if (row.key === 'starts' || row.key === 'ends') return fmtDate(raw);
  const value = raw?.trim() ?? '';
  return value || EMPTY;
}

function SyncCell({ row, side }: { row: SyncDiffRow; side: 'club' | 'meetup' }) {
  const club = side === 'club';
  const label = club ? 'Club' : 'Meetup';
  const cover = row.key === 'cover' ? (club ? row.club : row.meetup) : null;
  return (
    <View style={{
      flex: 1,
      minWidth: 140,
      gap: 4,
      backgroundColor: club ? colors.goldSoft : colors.headerBg,
      borderRadius: 6,
      padding: 10,
    }}>
      <Text style={[styles.fieldLabel, { color: club ? colors.warn : colors.muted, marginBottom: 0 }]}>{label}</Text>
      {row.key === 'cover' ? (
        cover ? <View style={{ opacity: club ? 1 : 0.55, alignSelf: 'flex-start' }}><EventCover url={cover} width={148} /></View>
          : <Text style={[styles.fieldValue, { color: colors.muted }]}>{EMPTY}</Text>
      ) : (
        <Text style={[styles.fieldValue, row.key === 'description' && { lineHeight: fs(20) }, !club && { color: colors.muted, textDecorationLine: 'line-through' }]}>
          {cellText(row, side)}
        </Text>
      )}
    </View>
  );
}

export function MeetupSyncCompare({ rows }: { rows: SyncDiffRow[] }) {
  const stacked = useWindowDimensions().width < 640;
  return (
    <View style={{ gap: 14 }}>
      {rows.map((row) => (
        <View key={row.key} style={{ gap: 8 }} accessibilityRole="text"
          accessibilityLabel={`${row.label}. Club ${cellText(row, 'club')}. Meetup ${cellText(row, 'meetup')}.`}>
          <View style={{ flexDirection: 'row', alignItems: 'center', gap: 6 }}>
            <Ionicons name={ICONS[row.key]} size={15} color={colors.navy} />
            <Text style={styles.colText}>{row.label}</Text>
          </View>
          <View style={stacked ? { gap: 8 } : { flexDirection: 'row', gap: 10 }}>
            <SyncCell row={row} side="club" />
            <SyncCell row={row} side="meetup" />
          </View>
        </View>
      ))}
    </View>
  );
}
