// Registers this device's Expo push token (native only). Free Expo push service; no paid features.
// Tapping a push opens the chat room (or the event, for a starting-soon notice).
import { AppState, Platform } from 'react-native';
import { useEffect, useRef } from 'react';
import AsyncStorage from '@react-native-async-storage/async-storage';
import * as Device from 'expo-device';
import * as Notifications from 'expo-notifications';
import Constants from 'expo-constants';
import { router } from 'expo-router';
import { expoProjectId, isExpoPushToken, notificationsAllowed, shouldPresentForegroundPush, shouldRequestNotificationPermission } from './push-rules';
import { PRODUCT_NAME } from './config';
import { supabase } from './supabase';

const LAST_PUSH_KEY = 'nycpprc:last-push';
const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

let activeRoomId: string | null = null;
const seenPushes = new Set<string>();

/** Room the member is looking at. A push for that room stays quiet. */
export function setActivePushRoom(roomId: string | null) {
  activeRoomId = roomId;
}

/** The thread on screen right now, if any. Online does not count as "looking at it". */
export function getActivePushRoom() {
  return activeRoomId;
}

/** `/rooms/:id` when the payload has a room, else `/events/:id`. */
export function hrefFromPushData(data: unknown): string | null {
  if (!data || typeof data !== 'object') return null;
  const rec = data as Record<string, unknown>;
  const roomId = typeof rec.roomId === 'string' ? rec.roomId : '';
  const eventId = typeof rec.eventId === 'string' ? rec.eventId : '';
  if (UUID.test(roomId)) return `/rooms/${roomId}`;
  if (UUID.test(eventId)) return `/events/${eventId}`;
  return null;
}

if (Platform.OS !== 'web') {
  Notifications.setNotificationHandler({
    handleNotification: async (notification) => {
      const data = notification.request.content.data;
      const roomId = data && typeof data.roomId === 'string' ? data.roomId : '';
      // Being in the app is not a mute. Hide the banner only for the open thread.
      const show = shouldPresentForegroundPush({ roomId, activeRoomId });
      return {
        shouldShowBanner: show,
        shouldShowList: show,
        shouldPlaySound: show,
        shouldSetBadge: false,
      };
    },
  });
}

async function openNotification(response: Notifications.NotificationResponse) {
  const id = response.notification.request.identifier;
  if (!id || seenPushes.has(id)) return;
  try {
    const prev = await AsyncStorage.getItem(LAST_PUSH_KEY);
    if (prev === id) { seenPushes.add(id); return; }
  } catch { /* still try to open */ }
  const href = hrefFromPushData(response.notification.request.content.data);
  if (!href) {
    seenPushes.add(id);
    try { await AsyncStorage.setItem(LAST_PUSH_KEY, id); } catch { /* ignore */ }
    return;
  }
  seenPushes.add(id);
  try {
    router.push(href);
    try { await AsyncStorage.setItem(LAST_PUSH_KEY, id); } catch { /* ignore */ }
  } catch {
    seenPushes.delete(id);
  }
}

/** Native only. Call once the signed-in navigation tree is up. */
export function usePushOpens(ready: boolean) {
  const queued = useRef<Notifications.NotificationResponse | null>(null);

  useEffect(() => {
    if (Platform.OS === 'web') return;
    const sub = Notifications.addNotificationResponseReceivedListener((response) => {
      if (!ready) { queued.current = response; return; }
      void openNotification(response);
    });
    return () => sub.remove();
  }, [ready]);

  useEffect(() => {
    if (Platform.OS === 'web' || !ready) return;
    const timer = setTimeout(() => {
      const waiting = queued.current;
      queued.current = null;
      if (waiting) { void openNotification(waiting); return; }
      void Notifications.getLastNotificationResponseAsync()
        .then((response) => { if (response) return openNotification(response); })
        .catch(() => {});
    }, 250);
    return () => clearTimeout(timer);
  }, [ready]);
}

function permissionInput(settings: Notifications.NotificationPermissionsStatus) {
  return {
    status: settings.status,
    granted: settings.granted,
    iosStatus: settings.ios?.status ?? null,
  };
}

export async function registerPushToken(userId: string) {
  if (Platform.OS === 'web' || !Device.isDevice) return;
  if (Platform.OS === 'android') {
    await Notifications.setNotificationChannelAsync('default', {
      name: PRODUCT_NAME,
      importance: Notifications.AndroidImportance.HIGH,
      sound: 'default',
    });
  }
  const current = await Notifications.getPermissionsAsync();
  let settings = current;
  if (!notificationsAllowed(permissionInput(current))) {
    // Denied stays denied until the member changes it in system settings.
    // The next foreground reads that grant and registers without asking again.
    if (!shouldRequestNotificationPermission(permissionInput(current))) return;
    settings = await Notifications.requestPermissionsAsync({
      ios: { allowAlert: true, allowBadge: true, allowSound: true },
    });
  }
  if (!notificationsAllowed(permissionInput(settings))) return;
  const extra = Constants.expoConfig?.extra as { eas?: { projectId?: string } } | undefined;
  const projectId = expoProjectId({
    expoConfigProjectId: extra?.eas?.projectId ?? null,
    easProjectId: Constants.easConfig?.projectId ?? null,
  });
  const { data: token } = await Notifications.getExpoPushTokenAsync({ projectId });
  if (!isExpoPushToken(token)) return;
  const { error } = await supabase.from('push_tokens').upsert(
    { token, user_id: userId, platform: Platform.OS, updated_at: new Date().toISOString() },
    { onConflict: 'token' },
  );
  if (error) throw error;
}

/** Register on sign-in and again whenever the app returns to the foreground. */
export function usePushRegistration(userId: string | null) {
  const pending = useRef<Promise<void> | null>(null);

  useEffect(() => {
    if (!userId) return;
    let live = true;
    const run = () => {
      if (!live || pending.current) return;
      const task = registerPushToken(userId).catch(() => {}).finally(() => {
        if (pending.current === task) pending.current = null;
      });
      pending.current = task;
    };
    run();
    const sub = AppState.addEventListener('change', (next) => {
      if (next === 'active') run();
    });
    return () => {
      live = false;
      pending.current = null;
      sub.remove();
    };
  }, [userId]);
}
