// Event visibility is a property of the club event, not of a publish channel.
// public  — listed once published; signed-in RSVP.
// private — listed teaser; RSVP is an application the owner approves.
// hidden  — unlisted secret link; not in directories; no web directory or Meetup; no plus-ones.

import type { EventVisibility } from './types';

export const EVENT_VISIBILITIES = ['public', 'private', 'hidden'] as const;

export const EVENT_VISIBILITY_OPTIONS: { value: EventVisibility; label: string }[] = [
  { value: 'public', label: 'Public' },
  { value: 'private', label: 'Private' },
  { value: 'hidden', label: 'Hidden' },
];

const VISIBILITY_HELP: Record<EventVisibility, string> = {
  public: 'Published events are searchable. Signed-in members RSVP.',
  private: 'A published teaser is searchable. People apply, and the owner approves. Applications stay off the public page.',
  hidden: 'Unlisted. Only the secret link opens it. RSVP requires an account, with no plus-ones. Never listed on the web directory or Meetup.',
};

export function eventVisibility(value: string | null | undefined): EventVisibility {
  if (value === 'private' || value === 'hidden') return value;
  return 'public';
}

export function eventVisibilityLabel(value: string | null | undefined): string {
  const visibility = eventVisibility(value);
  if (visibility === 'private') return 'Private';
  if (visibility === 'hidden') return 'Hidden';
  return 'Public';
}

export function eventVisibilityHelp(value: string | null | undefined): string {
  return VISIBILITY_HELP[eventVisibility(value)];
}

/** Web directory, group directory, and public search. Hidden is omitted. */
export function eventInPublicDirectory(event: { visibility?: string | null }): boolean {
  return eventVisibility(event.visibility) !== 'hidden';
}

/**
 * Member events list and its search. Hidden stays out unless this person
 * already has a reason to see it: moderator, owner, or an RSVP from the secret link.
 */
export function eventInMemberDirectory(
  event: { id: string; visibility?: string | null; owner_id?: string | null },
  viewer: { moderator: boolean; userId: string | null; attendingIds: ReadonlySet<string> },
): boolean {
  if (eventVisibility(event.visibility) !== 'hidden') return true;
  if (viewer.moderator) return true;
  if (viewer.userId != null && event.owner_id === viewer.userId) return true;
  return viewer.attendingIds.has(event.id);
}

/** Hidden events are not sent to the web directory or Meetup. */
export function hiddenBlocksPublish(value: string | null | undefined): boolean {
  return eventVisibility(value) === 'hidden';
}

/** App RSVP is one account. Hidden events have no plus-ones. */
export function allowsPlusOnes(value: string | null | undefined): boolean {
  return eventVisibility(value) !== 'hidden';
}

export function unlistedEventPath(token: string): string {
  return `/e/u/${token}`;
}

export function unlistedAttendPath(token: string): string {
  return `/e/u/${token}/attend`;
}

export type RsvpAction = 'attend' | 'apply' | 'pending' | 'none';

/** What the public or member page should offer. Pending is not an RSVP. */
export function rsvpAction(input: {
  visibility?: string | null;
  past: boolean;
  going: boolean;
  application?: 'pending' | 'approved' | 'declined' | null;
}): RsvpAction {
  if (input.past || input.going) return 'none';
  if (eventVisibility(input.visibility) !== 'private') return 'attend';
  if (input.application === 'approved') return 'attend';
  if (input.application === 'pending') return 'pending';
  return 'apply';
}
