// Design primitives: Lightning-style list → record structure in Gnosis Events brand colors.
import React from 'react';
import { ActivityIndicator, Image, Platform, Pressable, ScrollView, StyleSheet, Text, TextInput, TextInputProps, useWindowDimensions, View, ViewStyle } from 'react-native';
import { Ionicons } from '@expo/vector-icons';
import { router, type Href } from 'expo-router';
import { colors, dn, fonts, fs, maxWidth, radius, viewportWidth } from '../lib/theme';
import { avatarUrl, cachedMeetupPhoto, getMeetupPhoto } from '../lib/api';

type Variant = 'primary' | 'neutral' | 'secondary' | 'ghost' | 'danger' | 'destructive';
export function Button({ title, onPress, variant = 'primary', disabled, loading, small, style, icon, accessibilityLabel }: {
  title: string; onPress?: () => void; variant?: Variant; disabled?: boolean; loading?: boolean; small?: boolean; style?: ViewStyle; icon?: keyof typeof Ionicons.glyphMap; accessibilityLabel?: string;
}) {
  const v = variant === 'secondary' ? 'neutral' : variant;
  const bg = v === 'primary' ? colors.navy : v === 'destructive' ? colors.danger : v === 'ghost' ? 'transparent' : '#fff';
  const fg = v === 'primary' || v === 'destructive' ? '#fff' : v === 'danger' ? colors.danger : colors.navy;
  const border = v === 'primary' ? colors.navy : v === 'destructive' ? colors.danger : v === 'ghost' ? 'transparent' : v === 'danger' ? '#e2b9b0' : colors.lineStrong;
  return (
    <Pressable accessibilityRole="button" accessibilityLabel={accessibilityLabel} onPress={onPress} disabled={disabled || loading}
      style={({ pressed }) => [styles.btn, small && styles.btnSm, { backgroundColor: bg, borderColor: border, opacity: disabled ? 0.5 : pressed ? 0.8 : 1 }, style]}>
      {loading ? <ActivityIndicator color={fg} size="small" /> : (
        <View style={{ flexDirection: 'row', alignItems: 'center', gap: 6 }}>
          {icon ? <Ionicons name={icon} size={small ? 14 : 16} color={fg} /> : null}
          <Text style={[styles.btnText, small && { fontSize: fs(13) }, { color: fg }]}>{title}</Text>
        </View>)}
    </Pressable>
  );
}

export function Field(props: TextInputProps & { label?: string; help?: string }) {
  return (
    <View style={{ marginBottom: 14 }}>
      {props.label ? <Text style={styles.label}>{props.label}</Text> : null}
      <TextInput placeholderTextColor="#9aa1ad" {...props} style={[styles.input, props.multiline && { minHeight: 90, textAlignVertical: 'top' }, props.style]} />
      {props.help ? <Text style={[styles.muted, { fontSize: fs(12), marginTop: 4 }]}>{props.help}</Text> : null}
    </View>
  );
}

export function Avatar({ name, path, uri, userId, size = 36, online }: { name: string; path?: string | null; uri?: string | null; userId?: string | null; size?: number; online?: boolean }) {
  const own = avatarUrl(path ?? null) ?? uri ?? null;
  const [meetup, setMeetup] = React.useState<string | null>(() => (userId ? cachedMeetupPhoto(userId) ?? null : null));
  React.useEffect(() => {
    if (own || !userId) return;
    let live = true;
    getMeetupPhoto(userId).then((u) => { if (live) setMeetup(u); });
    return () => { live = false; };
  }, [own, userId]);
  const url = own ?? (userId ? meetup : null);
  const initials = name.split(/\s+/).map((s) => s[0]).join('').slice(0, 2).toUpperCase();
  const hue = [...name].reduce((a, c) => a + c.charCodeAt(0), 0) % 4;
  const bgs = [colors.navy, '#3d5a80', '#7a5c2e', '#4b6b5a'];
  return (
    <View style={{ width: size, height: size }}>
      {url ? <Image source={{ uri: url }} style={{ width: size, height: size, borderRadius: size / 2 }} /> :
        <View style={{ width: size, height: size, borderRadius: size / 2, backgroundColor: bgs[hue], alignItems: 'center', justifyContent: 'center' }}>
          <Text style={{ color: '#fff', fontFamily: fonts.sansBold, fontSize: size * 0.38 }}>{initials}</Text>
        </View>}
      {online ? <View style={[styles.dot, { right: -1, bottom: -1 }]} /> : null}
    </View>
  );
}

/** Avatar and name. RSVP rows, member rows, and the owner field all use this. */
export function PersonFace({ name, label, subtitle, path, uri, userId, size = 28, fill = false, style }: {
  name: string;
  /** Visible name. Defaults to `name`. RSVP rows append “ · host” without changing the initials. */
  label?: string;
  subtitle?: string | null;
  path?: string | null;
  uri?: string | null;
  userId?: string | null;
  size?: number;
  /** Fill the parent column so a long name truncates, as in a list row. */
  fill?: boolean;
  style?: ViewStyle;
}) {
  return (
    <View style={[{ flexDirection: 'row', alignItems: 'center', gap: 8, minWidth: 0 }, fill ? { flex: 1 } : null, style]}>
      <Avatar name={name} path={path} uri={uri} userId={userId} size={size} />
      <View style={{ flexShrink: 1, minWidth: 0, flex: fill ? 1 : undefined }}>
        <Text numberOfLines={1} style={styles.rowPrimary}>{label ?? name}</Text>
        {subtitle ? <Text numberOfLines={1} style={[styles.muted, { fontSize: fs(12) }]}>{subtitle}</Text> : null}
      </View>
    </View>
  );
}

export function Card({ children, style }: { children: React.ReactNode; style?: ViewStyle }) {
  return <View style={[styles.card, style]}>{children}</View>;
}

export function DemoBanner() {
  return <View style={styles.demo}><Text style={styles.demoText}>Demo · sample data</Text></View>;
}

type Tone = 'default' | 'success' | 'warning' | 'danger' | 'info' | 'gold';
const TONES: Record<Tone, [string, string]> = {
  default: ['#eeeae1', colors.muted], success: [colors.onlineSoft, colors.online], warning: [colors.goldSoft, colors.warn],
  danger: [colors.dangerSoft, colors.danger], info: [colors.navySoft, colors.navy], gold: [colors.goldSoft, colors.navyDark],
};
export function StatusPill({ label, tone = 'default' }: { label: string; tone?: Tone }) {
  const [bg, fg] = TONES[tone];
  return <View style={[styles.pill, { backgroundColor: bg }]}><Text style={[styles.pillText, { color: fg }]}>{label}</Text></View>;
}

/** Icon only. Sits in the page, not in a stack title bar. */
export function BackChevron({ fallback }: { fallback: Href }) {
  return (
    <Pressable
      accessibilityRole="button"
      accessibilityLabel="Back"
      hitSlop={8}
      onPress={() => { if (router.canGoBack()) router.back(); else router.replace(fallback); }}
      style={{ alignSelf: 'flex-start', marginLeft: -8, marginBottom: dn(-8, -2), padding: 4 }}
    >
      <Ionicons name="chevron-back" size={22} color={colors.navy} />
    </Pressable>
  );
}

/** Scrollable page body: paper background, centered column. `fill` lets a child list take the remaining height (use with `scroll={false}`). */
export function Page({ children, scroll = true, refreshControl, fill = false, scrollRef, contentWidth }: {
  children: React.ReactNode; scroll?: boolean; refreshControl?: any; fill?: boolean;
  /** Native scroll view, so a map can freeze scrolling without re-rendering the page. */
  scrollRef?: React.Ref<React.ComponentRef<typeof ScrollView>>;
  /** Override the centered column width. The public group page is wider than a record. */
  contentWidth?: number;
}) {
  const inner = <View style={[styles.pageInner, contentWidth != null ? { maxWidth: contentWidth } : null, fill && { flex: 1, minHeight: 0 }]}>{children}</View>;
  return scroll
    ? <ScrollView ref={scrollRef} style={{ flex: 1 }} contentContainerStyle={{ paddingBottom: 32 }} refreshControl={refreshControl}>{inner}</ScrollView>
    : <View style={{ flex: 1, minHeight: 0 }}>{inner}</View>;
}

/** List-view header: object label, title, record count, actions. */
export function PageHeader({ icon, eyebrow, title, subtitle, actions }: {
  icon?: keyof typeof Ionicons.glyphMap; eyebrow?: string; title: string; subtitle?: string | null; actions?: React.ReactNode;
}) {
  return (
    <View style={styles.pageHeader}>
      <View style={{ flexDirection: 'row', alignItems: 'center', gap: dn(12, 11), flex: 1, minWidth: 200 }}>
        {icon ? <View style={styles.headerIcon}><Ionicons name={icon} size={dn(20, 17)} color="#fff" /></View> : null}
        <View style={{ flex: 1 }}>
          {eyebrow ? <Text style={styles.eyebrow}>{eyebrow}</Text> : null}
          <Text style={styles.h1} numberOfLines={2}>{title}</Text>
          {subtitle ? <Text style={[styles.muted, { fontSize: fs(13), marginTop: 2 }]}>{subtitle}</Text> : null}
        </View>
      </View>
      {actions ? <View style={styles.actions}>{actions}</View> : null}
    </View>
  );
}

/** Search/filter bar for list views. */
export function Toolbar({ search, onSearch, placeholder = 'Search this list…', children }: {
  search?: string; onSearch?: (s: string) => void; placeholder?: string; children?: React.ReactNode;
}) {
  return (
    <View style={styles.toolbar}>
      {onSearch ? (
        <View style={styles.searchBox}>
          <Ionicons name="search" size={15} color={colors.faint} />
          <TextInput value={search} onChangeText={onSearch} placeholder={placeholder} placeholderTextColor="#9aa1ad" autoCapitalize="none"
            style={[{ flex: 1, fontFamily: fonts.sans, fontSize: fs(14), color: colors.ink, paddingVertical: dn(8, 7) }, Platform.OS === 'web' ? ({ outlineWidth: 0 } as any) : null]} />
        </View>) : null}
      {children ? <View style={{ flexDirection: 'row', gap: 6, flexWrap: 'wrap', alignItems: 'center' }}>{children}</View> : null}
    </View>
  );
}

/** Segmented filter buttons. */
export function Segmented<T extends string | number>({ value, options, onChange }: { value: T; options: { value: T; label: string }[]; onChange: (v: T) => void }) {
  return (
    <View style={styles.segmented}>
      {options.map((o, i) => {
        const on = o.value === value;
        return (
          <Pressable key={String(o.value)} onPress={() => onChange(o.value)} accessibilityRole="button"
            style={[styles.segment, i > 0 && { borderLeftWidth: 1, borderLeftColor: colors.lineStrong }, on && { backgroundColor: colors.navy }]}>
            <Text style={{ fontFamily: fonts.sansMedium, fontSize: fs(13), color: on ? '#fff' : colors.navy }}>{o.label}</Text>
          </Pressable>);
      })}
    </View>
  );
}

export type Column = { label: string; flex?: number; width?: number; minWidth?: number; align?: 'left' | 'right' };

// Shared by headers and cells so the two stay on the same grid. Flex columns
// must be able to shrink below their text (minWidth 0); otherwise a long value
// paints over the next column. Fixed columns keep the width they were given.
function columnBox(col?: Column): ViewStyle {
  if (col?.width != null) {
    const width = col.width;
    return { width, minWidth: col.minWidth ?? width, flexGrow: 0, flexShrink: 0, overflow: 'hidden' };
  }
  return { flex: col?.flex ?? 1, minWidth: col?.minWidth ?? 0, overflow: 'hidden' };
}

/** Column titles aligned with `ListRow` cells (includes the chevron gutter). */
export function ListColumnHeader({ columns }: { columns: Column[] }) {
  return (
    <View style={styles.colHeader}>
      {columns.map((c) => (
        <View key={c.label} style={[columnBox(c), { alignItems: c.align === 'right' ? 'flex-end' : 'stretch' }]}>
          <Text numberOfLines={1} style={[styles.colText, { maxWidth: '100%', textAlign: c.align ?? 'left' }, c.align === 'right' ? { width: '100%' } : null]}>{c.label}</Text>
        </View>))}
      <View style={{ width: 18 }} />
    </View>
  );
}

/** Card containing column headers + rows. */
export function ListView({ title, note, count, columns, children, empty, loading, footer }: {
  title?: string; note?: string; count?: number; columns?: Column[]; children?: React.ReactNode; empty?: React.ReactNode; loading?: boolean; footer?: React.ReactNode;
}) {
  const hasRows = React.Children.toArray(children).filter(Boolean).length > 0;
  return (
    <View style={styles.listCard}>
      {title ? <View style={styles.listTitle}>
        {note ? <View style={{ flex: 1, minWidth: 0, gap: 2 }}>
          <Text style={styles.sectionTitle}>{title}</Text>
          <Text style={[styles.muted, { fontSize: fs(12), lineHeight: fs(16) }]}>{note}</Text>
        </View> : <Text style={styles.sectionTitle}>{title}</Text>}
        {count != null ? <Text style={[styles.muted, { fontSize: fs(12) }]}>{count} {count === 1 ? 'item' : 'items'}</Text> : null}
      </View> : null}
      {columns && hasRows ? <ListColumnHeader columns={columns} /> : null}
      {loading ? <View style={{ padding: 20 }}><ActivityIndicator color={colors.navy} /></View> : hasRows ? children : empty}
      {footer}
    </View>
  );
}

/** Clickable row → navigates to a record page. Pass `cells` for tabular rows or `children` for custom content. */
export function ListRow({ onPress, cells, columns, children, leading, dim, accessibilityLabel }: {
  onPress?: () => void; cells?: React.ReactNode[]; columns?: Column[]; children?: React.ReactNode; leading?: React.ReactNode; dim?: boolean; accessibilityLabel?: string;
}) {
  return (
    <Pressable onPress={onPress} disabled={!onPress} accessibilityRole={onPress ? 'link' : undefined} accessibilityLabel={accessibilityLabel}>
      {({ pressed, hovered }: any) => (
        <View style={[styles.row, (pressed || hovered) && onPress ? { backgroundColor: colors.rowHover } : null, dim && { opacity: 0.6 }]}>
          {leading}
          {cells ? cells.map((c, i) => {
            const col = columns?.[i];
            const right = col?.align === 'right';
            return (
              <View key={i} style={[columnBox(col), { alignItems: right ? 'flex-end' : 'stretch' }]}>
                {typeof c === 'string' || typeof c === 'number'
                  ? <Text numberOfLines={1} style={[i === 0 ? styles.rowPrimary : styles.rowCell, right ? { width: '100%', textAlign: 'right' } : { maxWidth: '100%' }]}>{c}</Text>
                  : c}
              </View>);
          }) : <View style={{ flex: 1, minWidth: 0 }}>{children}</View>}
          {onPress ? <Ionicons name="chevron-forward" size={16} color={colors.faint} style={{ width: 18 }} /> : null}
        </View>
      )}
    </Pressable>
  );
}

/** Below this strip width, two columns crush a Zoom URL and a long group name. */
const HIGHLIGHT_STACK_BELOW = 420;

function HighlightFields({ fields }: { fields: [string, React.ReactNode][] }) {
  const windowWidth = viewportWidth(useWindowDimensions().width);
  const [width, setWidth] = React.useState(0);
  // Page padding plus the card padding, until onLayout reports the strip itself.
  const measured = width || (windowWidth > 0 ? Math.min(windowWidth, maxWidth) - 64 : 0);
  const stack = measured > 0 && measured < HIGHLIGHT_STACK_BELOW;
  return (
    <View
      style={styles.highlightFields}
      onLayout={(e) => {
        const next = Math.round(e.nativeEvent.layout.width);
        setWidth((cur) => (cur === next ? cur : next));
      }}
    >
      {fields.map(([k, v]) => (
        <View key={k} style={stack ? styles.highlightFieldStack : styles.highlightField}>
          <Text style={styles.fieldLabel}>{k}</Text>
          {typeof v === 'string' || typeof v === 'number' ? <Text style={styles.fieldValue}>{v}</Text> : v}
        </View>
      ))}
    </View>
  );
}

/** Record page highlight panel: icon/avatar, title, key fields, primary actions. */
export function HighlightPanel({ icon, media, eyebrow, title, subtitle, pills, fields, actions, children }: {
  icon?: keyof typeof Ionicons.glyphMap; media?: React.ReactNode; eyebrow?: string; title: string; subtitle?: string | null;
  pills?: React.ReactNode; fields?: [string, React.ReactNode][]; actions?: React.ReactNode; children?: React.ReactNode;
}) {
  return (
    <View style={styles.highlight}>
      <View style={{ flexDirection: 'row', gap: 14, alignItems: 'flex-start', flexWrap: 'wrap' }}>
        {media ?? (icon ? <View style={[styles.headerIcon, { width: 44, height: 44 }]}><Ionicons name={icon} size={22} color="#fff" /></View> : null)}
        <View style={{ flex: 1, minWidth: 180 }}>
          {eyebrow ? <Text style={styles.eyebrow}>{eyebrow}</Text> : null}
          <Text style={styles.h1}>{title}</Text>
          {subtitle ? <Text style={[styles.muted, { marginTop: 2 }]}>{subtitle}</Text> : null}
          {pills ? <View style={{ flexDirection: 'row', gap: 6, marginTop: 8, flexWrap: 'wrap' }}>{pills}</View> : null}
        </View>
        {actions ? <View style={styles.actions}>{actions}</View> : null}
      </View>
      {fields?.length ? <HighlightFields fields={fields} /> : null}
      {children}
    </View>
  );
}

/** Detail section / related list card. */
export function SectionCard({ title, actions, children, padded = true }: { title?: string; actions?: React.ReactNode; children: React.ReactNode; padded?: boolean }) {
  return (
    <View style={styles.listCard}>
      {title ? <View style={styles.listTitle}><Text style={styles.sectionTitle}>{title}</Text>{actions}</View> : null}
      <View style={padded ? { padding: 16 } : undefined}>{children}</View>
    </View>
  );
}

/** Label/value pairs in a two-column grid. */
export function FieldGrid({ fields }: { fields: [string, React.ReactNode][] }) {
  return (
    <View style={{ flexDirection: 'row', flexWrap: 'wrap', rowGap: 14, columnGap: 20 }}>
      {fields.map(([k, v]) => (
        <View key={k} style={{ flexBasis: 220, flexGrow: 1, borderBottomWidth: 1, borderBottomColor: colors.line, paddingBottom: 8 }}>
          <Text style={styles.fieldLabel}>{k}</Text>
          {typeof v === 'string' || typeof v === 'number' ? <Text style={styles.fieldValue}>{v === '' ? '—' : v}</Text> : v ?? <Text style={styles.fieldValue}>—</Text>}
        </View>))}
    </View>
  );
}

/** Centered empty panel. `compact` is one list row — same density as `ListRow` — for a section that should stay in the list rhythm. */
export function EmptyState({ icon = 'file-tray-outline', title, body, action, compact = false }: {
  icon?: keyof typeof Ionicons.glyphMap; title: string; body?: string; action?: React.ReactNode; compact?: boolean;
}) {
  if (compact) {
    return (
      <View style={[styles.row, { borderBottomWidth: 0 }]} accessibilityRole="text">
        <View style={[styles.headerIcon, { backgroundColor: colors.headerBg }]}>
          <Ionicons name={icon} size={18} color={colors.muted} />
        </View>
        <View style={{ flex: 1, minWidth: 0 }}>
          <Text style={styles.rowPrimary} numberOfLines={1}>{title}</Text>
          {body ? <Text style={[styles.muted, { fontSize: fs(12), lineHeight: fs(16), marginTop: 2 }]}>{body}</Text> : null}
          {action ? <View style={{ marginTop: 8 }}>{action}</View> : null}
        </View>
      </View>
    );
  }
  return (
    <View style={{ alignItems: 'center', padding: 28, gap: 6 }}>
      <Ionicons name={icon} size={30} color={colors.faint} />
      <Text style={[styles.body, { fontFamily: fonts.sansMedium }]}>{title}</Text>
      {body ? <Text style={[styles.muted, { textAlign: 'center', maxWidth: 380 }]}>{body}</Text> : null}
      {action ? <View style={{ marginTop: 8 }}>{action}</View> : null}
    </View>
  );
}

export function ErrorText({ children }: { children?: string | null }) {
  return children ? <View style={styles.errorBox}><Ionicons name="alert-circle" size={16} color={colors.danger} /><Text style={{ color: colors.danger, fontFamily: fonts.sans, flex: 1 }}>{children}</Text></View> : null;
}

