// Confirm sheet for deleting a club event. The destructive button is in this sheet.
import React, { useEffect, useState } from 'react';
import { Pressable, Text, View } from 'react-native';
import { Ionicons } from '@expo/vector-icons';
import { ConfirmSheet, IncludedRow } from './confirm-sheet';
import { styles } from './ui';
import { colors, fs } from '../lib/theme';

export function DeleteEventSheet({ visible, meetupLinked, busy, error, onCancel, onConfirm }: {
  visible: boolean;
  meetupLinked: boolean;
  busy: boolean;
  error: string | null;
  onCancel: () => void;
  onConfirm: (options: { unlinkMeetup: boolean }) => void;
}) {
  const [unlink, setUnlink] = useState(false);
  useEffect(() => { if (visible) setUnlink(false); }, [visible]);
  return (
    <ConfirmSheet visible={visible} title="Delete this event?" busy={busy} error={error} confirmTitle="Delete event"
      body={meetupLinked
        ? 'This removes it from Gnosis Events. The Meetup listing is not cancelled.'
        : 'This removes it from Gnosis Events.'}
      onCancel={onCancel}
      onConfirm={() => onConfirm({ unlinkMeetup: meetupLinked && unlink })}>
      <View style={{ gap: 10 }}>
        <IncludedRow label="The club event" />
        <IncludedRow label="Club RSVPs for this event" />
        <IncludedRow label="The public web page, when one exists" />
      </View>
      {meetupLinked ? (
        <Pressable onPress={() => { if (!busy) setUnlink((v) => !v); }} accessibilityRole="checkbox" accessibilityState={{ checked: unlink, disabled: busy }}
          style={{ flexDirection: 'row', alignItems: 'flex-start', gap: 10 }}>
          <Ionicons name={unlink ? 'checkbox' : 'square-outline'} size={20} color={colors.navy} style={{ marginTop: 2 }} />
          <View style={{ flex: 1 }}>
            <Text style={styles.body}>Unlink from Meetup</Text>
            <Text style={[styles.muted, { fontSize: fs(13) }]}>Clears the Meetup link stored in Gnosis Events. Meetup itself is left as it is.</Text>
          </View>
        </Pressable>
      ) : null}
    </ConfirmSheet>
  );
}
