import { Platform } from 'react-native';
import * as Crypto from 'expo-crypto';
import * as LocalAuthentication from 'expo-local-authentication';
import * as SecureStore from 'expo-secure-store';
import { biometricStorageKey, encodeUnlockMarker, type BiometricKind } from './biometric-policy';

// The preference and the unlock marker live in the device keychain / keystore.
// They are not the Google, Apple, or email credentials, and not the Supabase refresh token.
function storeOptions(): SecureStore.SecureStoreOptions {
  if (Platform.OS !== 'ios') return {};
  return { keychainAccessible: SecureStore.WHEN_UNLOCKED_THIS_DEVICE_ONLY };
}

const KIND: Partial<Record<LocalAuthentication.AuthenticationType, BiometricKind>> = {
  [LocalAuthentication.AuthenticationType.FINGERPRINT]: 'fingerprint',
  [LocalAuthentication.AuthenticationType.FACIAL_RECOGNITION]: 'face',
  [LocalAuthentication.AuthenticationType.IRIS]: 'iris',
};

export type BiometricCapability = { hasHardware: boolean; enrolled: boolean; kinds: BiometricKind[] };

export async function readBiometricCapability(): Promise<BiometricCapability> {
  if (Platform.OS === 'web') return { hasHardware: false, enrolled: false, kinds: [] };
  const [hasHardware, enrolled, types] = await Promise.all([
    LocalAuthentication.hasHardwareAsync(),
    LocalAuthentication.isEnrolledAsync(),
    LocalAuthentication.supportedAuthenticationTypesAsync(),
  ]);
  const kinds: BiometricKind[] = [];
  for (const type of types) {
    const kind = KIND[type];
    if (kind && !kinds.includes(kind)) kinds.push(kind);
  }
  return { hasHardware, enrolled, kinds };
}

export async function readBiometricEnabled(userId: string): Promise<boolean> {
  const key = biometricStorageKey('enabled', userId);
  if (!key || Platform.OS === 'web') return false;
  try {
    return (await SecureStore.getItemAsync(key, storeOptions())) === '1';
  } catch {
    // A keychain miss should not trap someone behind a lock they cannot dismiss
    // except through the account fallback. The next successful read still locks.
    return false;
  }
}

export async function writeBiometricEnabled(userId: string, on: boolean): Promise<void> {
  const key = biometricStorageKey('enabled', userId);
  if (!key || Platform.OS === 'web') return;
  const options = storeOptions();
  if (!on) {
    await SecureStore.deleteItemAsync(key, options).catch(() => {});
    await clearUnlockMarker(userId);
    return;
  }
  await SecureStore.setItemAsync(key, '1', options);
}

export async function writeUnlockMarker(userId: string): Promise<void> {
  const key = biometricStorageKey('marker', userId);
  if (!key || Platform.OS === 'web') return;
  const raw = encodeUnlockMarker({ at: Date.now(), token: Crypto.randomUUID() });
  await SecureStore.setItemAsync(key, raw, storeOptions());
}

export async function clearUnlockMarker(userId: string): Promise<void> {
  const key = biometricStorageKey('marker', userId);
  if (!key || Platform.OS === 'web') return;
  await SecureStore.deleteItemAsync(key, storeOptions()).catch(() => {});
}

/**
 * Biometric only. The device passcode is not a success: the lock screen sends
 * the member back through Google, Apple, or email instead.
 * Android accepts weak or strong biometrics so face unlock and fingerprint both work.
 */
export async function promptBiometric(promptMessage: string): Promise<{ ok: true } | { ok: false; error: string }> {
  if (Platform.OS === 'web') return { ok: false, error: 'not_available' };
  const result = await LocalAuthentication.authenticateAsync({
    promptMessage,
    cancelLabel: 'Cancel',
    disableDeviceFallback: true,
    fallbackLabel: '',
    requireConfirmation: false,
    biometricsSecurityLevel: 'weak',
  });
  if (result.success) return { ok: true };
  return { ok: false, error: result.error };
}
