// Publish-to related list. Meetup and Web (and any later channel row) share one shape:
// status, in sync / out of date, last published, and the snapshot that was sent.
import React, { useCallback, useState } from 'react';
import { Linking, Text, useWindowDimensions, View } from 'react-native';
import { router, Stack, useFocusEffect } from 'expo-router';
import { EventCover } from './events';
import { MeetupSyncCompare } from './meetup-sync';
import { EntityTitle } from './record-chrome';
import { BackChevron, Button, EmptyState, ErrorText, FieldGrid, ListRow, ListView, Page, SectionCard, StatusPill, styles, type Column } from './ui';
import {
  copyPublicEventLink, getEventForEdit, listEventPublications, meetupEventAction, publicEventPath, publicEventUrl, setEventPublished,
} from '../lib/events';
import { hiddenBlocksPublish } from '../lib/event-visibility';
import { channelLabel, publicationOutOfDate, publicationStatus, publicationSync, publishedVersionLine, PUBLISH_CHANNELS, safeMeetupUrl } from '../lib/publications';
import { shareActionTitle } from '../lib/share-link';
import { meetupSyncRows } from '../lib/meetup-sync';
import { fmtDate } from '../lib/format';
import { fs } from '../lib/theme';
import type { ClubEvent, EventPublication, EventSnapshot } from '../lib/types';

const PUBLISH_COLS: Column[] = [
  { label: 'Channel', flex: 1.2 },
  { label: 'Status', width: 120 },
  { label: 'Sync', width: 120 },
  { label: 'Last published', width: 180 },
];
const WIDE = 640;

type ChannelPublication = {
  channel: string;
  status: string;
  published_version: number | null;
  published_at: string | null;
};

/** Publish-to related list. Events and groups pass their own rows and open handler. */
export function PublishChannelList({ currentVersion, rows, error, onOpen, footnote }: {
  currentVersion: number;
  rows: ChannelPublication[] | null;
  error: string | null;
  onOpen: (channel: string) => void;
  footnote: string;
}) {
  const { width } = useWindowDimensions();
  const wide = width >= WIDE;
  const byChannel = new Map((rows ?? []).map((p) => [p.channel, p]));
  const extras = (rows ?? []).map((p) => p.channel).filter((c) => c !== 'meetup' && c !== 'web');
  const channels = [...PUBLISH_CHANNELS.map((c) => c.channel), ...extras];
  return (
    <View style={{ gap: 8 }}>
      <ErrorText>{error}</ErrorText>
      <ListView title="Publish to" count={rows ? channels.length : undefined} columns={wide ? PUBLISH_COLS : undefined}
        loading={!rows && !error}
        empty={<EmptyState icon="cloud-upload-outline" title="No channels" />}>
        {rows ? channels.map((channel) => (
          <PublishRow key={channel} wide={wide} currentVersion={currentVersion} channel={channel} pub={byChannel.get(channel) ?? null} onOpen={onOpen} />
        )) : null}
      </ListView>
      <Text style={[styles.muted, { fontSize: fs(13) }]}>{footnote}</Text>
    </View>
  );
}

export function PublishToList({ event }: { event: ClubEvent }) {
  const [rows, setRows] = useState<EventPublication[] | null>(null);
  const [err, setErr] = useState<string | null>(null);
  const load = useCallback(async () => {
    try { setRows(await listEventPublications(event.id)); setErr(null); }
    catch (e: any) { setErr(e.message); }
  }, [event.id]);
  useFocusEffect(useCallback(() => { load(); }, [load]));
  const open = useCallback((channel: string) => {
    router.push(`/events/${event.id}/publish/${encodeURIComponent(channel)}`);
  }, [event.id]);
  return (
    <PublishChannelList currentVersion={event.current_version} rows={rows} error={err} onOpen={open}
      footnote="Edits stay on this club event until you publish." />
  );
}

function PublishRow({ wide, currentVersion, channel, pub, onOpen }: {
  wide: boolean; currentVersion: number; channel: string; pub: ChannelPublication | null; onOpen: (channel: string) => void;
}) {
  const status = publicationStatus(pub);
  const sync = publicationSync(currentVersion, pub);
  const when = pub?.published_at ? fmtDate(pub.published_at) : '—';
  const open = () => onOpen(channel);
  const label = channelLabel(channel);
  if (!wide) {
    return (
      <ListRow onPress={open} accessibilityLabel={`Publish to ${label}`}>
        <View style={{ flex: 1, minWidth: 0, gap: 6 }}>
          <Text style={styles.rowPrimary}>{label}</Text>
          <View style={{ flexDirection: 'row', flexWrap: 'wrap', gap: 8, alignItems: 'center' }}>
            <StatusPill label={status.label} tone={status.tone} />
            {sync ? <StatusPill label={sync.label} tone={sync.tone} /> : null}
            <Text style={styles.rowCell} numberOfLines={1}>{when}</Text>
          </View>
        </View>
      </ListRow>
    );
  }
  return (
    <ListRow columns={PUBLISH_COLS} onPress={open} accessibilityLabel={`Publish to ${label}`}
      cells={[label, <StatusPill label={status.label} tone={status.tone} />, sync ? <StatusPill label={sync.label} tone={sync.tone} /> : '—', when]} />
  );
}

export function PublishLinkLine({ children }: { children: string }) {
  return <Text selectable style={[styles.muted, { marginTop: 8 }]}>{children}</Text>;
}

export function PublishConfirmLine({ children }: { children: string }) {
  return <Text style={[styles.muted, { marginTop: 10 }]}>{children}</Text>;
}

/** Channel page shell. Event and group publish keep their own actions. */
export function PublishRecordPage({ label, subtitle, status, sync, fields, error, note, lastError, body, versionLine, extras, actions, snapshot, backFallback, snapshotTitle = 'Snapshot sent', lead, showSnapshot = true }: {
  label: string;
  backFallback: string;
  subtitle?: string | null;
  status: { label: string; tone: 'default' | 'success' | 'danger' };
  sync: { label: string; tone: 'success' | 'warning' } | null;
  fields: [string, React.ReactNode][];
  error: string | null;
  note: string | null;
  lastError: string | null;
  body: string | null;
  versionLine: string | null;
  extras?: React.ReactNode;
  actions: React.ReactNode;
  snapshot: React.ReactNode | null;
  snapshotTitle?: string;
  /** Shown above the action card. The Meetup field comparison uses this. */
  lead?: React.ReactNode;
  showSnapshot?: boolean;
}) {
  return (
    <Page>
      {/* Channel name is the serif title below. The stack bar repeated it. */}
      <Stack.Screen options={{ title: label, headerShown: false }} />
      <BackChevron fallback={backFallback} />
      <EntityTitle title={label} meta={subtitle} pills={<><StatusPill label={status.label} tone={status.tone} />{sync ? <StatusPill label={sync.label} tone={sync.tone} /> : null}</>} />
      {fields.length ? <FieldGrid fields={fields} /> : null}
      <ErrorText>{error}</ErrorText>
      {note ? <Text style={[styles.muted, { fontSize: fs(13) }]}>{note}</Text> : null}
      {lastError ? <ErrorText>{lastError}</ErrorText> : null}
      {lead}
      {/* Hero already names the channel. A second Web or Meetup heading here only repeats it. */}
      <SectionCard>
        {body ? <Text style={styles.body}>{body}</Text> : null}
        {versionLine ? <Text style={[styles.muted, body ? { marginTop: 8 } : null, { fontSize: fs(13) }]}>{versionLine}</Text> : null}
        {extras}
        <View style={{ flexDirection: 'row', flexWrap: 'wrap', gap: 8, marginTop: 12 }}>{actions}</View>
      </SectionCard>
      {showSnapshot ? <SectionCard title={snapshotTitle}>
        {snapshot ?? <Text style={styles.body}>Nothing has been sent to {label} yet.</Text>}
      </SectionCard> : null}
    </Page>
  );
}

export function usePublishAction(reload: () => Promise<void>) {
  const [err, setErr] = useState<string | null>(null);
  const [note, setNote] = useState<string | null>(null);
  const [busy, setBusy] = useState<string | null>(null);
  const run = async (name: string, fn: () => Promise<string>, after?: () => void) => {
    setBusy(name); setErr(null); setNote(null);
    try { setNote(await fn()); after?.(); await reload(); }
    catch (e: any) { setErr(e.message); }
    finally { setBusy(null); }
  };
  return { err, setErr, note, busy, run };
}

export function useCopiedShare(setErr: (message: string | null) => void) {
  const [copied, setCopied] = useState(false);
  const copy = async (fn: () => Promise<'copied' | 'shared' | 'dismissed'>) => {
    setErr(null);
    try {
      const how = await fn();
      if (how === 'copied') { setCopied(true); setTimeout(() => setCopied(false), 5000); }
    } catch (e: any) { setErr(e.message); }
  };
  return { copy, title: shareActionTitle(copied) };
}

function SnapshotBody({ snapshot }: { snapshot: EventSnapshot }) {
  return (
    <>
      {snapshot.image_url ? <View style={{ marginBottom: 12 }}><EventCover url={snapshot.image_url} width={220} /></View> : null}
      <FieldGrid fields={[
        ['Title', snapshot.title],
        ['Starts', fmtDate(snapshot.starts_at)],
        ['Ends', fmtDate(snapshot.ends_at)],
        ['Venue', snapshot.venue_name ?? '—'],
        ['Address', snapshot.venue_address ?? '—'],
      ]} />
      {snapshot.description ? <Text style={[styles.body, { marginTop: 14 }]}>{snapshot.description}</Text> : null}
    </>
  );
}

export function PublishChannelScreen({ eventId, channel }: { eventId: string; channel: string }) {
  const [event, setEvent] = useState<ClubEvent | null | undefined>(undefined);
  const [pub, setPub] = useState<EventPublication | null>(null);
  const [confirming, setConfirming] = useState<null | 'unpublish' | 'cancel' | 'pull'>(null);
  const load = useCallback(async () => {
    const e = await getEventForEdit(eventId);
    setEvent(e);
    if (!e) { setPub(null); return; }
    const rows = await listEventPublications(e.id);
    setPub(rows.find((p) => p.channel === channel) ?? null);
  }, [eventId, channel]);
  const { err, setErr, note, busy, run } = usePublishAction(load);
  const { copy, title: copyTitle } = useCopiedShare(setErr);
  useFocusEffect(useCallback(() => { load().catch((e) => setErr(e.message)); }, [load, setErr]));
  const clearConfirm = () => setConfirming(null);

  const backFallback = `/events/${eventId}`;
  if (event === undefined) return <Page><BackChevron fallback={backFallback} /><ErrorText>{err}</ErrorText></Page>;
  if (event === null) return <Page><BackChevron fallback="/events" /><EmptyState icon="calendar-outline" title="Event not found" /></Page>;

  const label = channelLabel(channel);
  const status = publicationStatus(pub);
  const sync = publicationSync(event.current_version, pub);
  const linked = !!(event.meetup_id || pub?.external_id);
  const cancelled = channel === 'meetup' && (pub?.status === 'cancelled' || event.meetup_publish_status === 'CANCELLED');
  const webOn = channel === 'web' && pub?.status === 'published' && !event.archived;
  const meetupOn = channel === 'meetup' && pub?.status === 'published' && !cancelled;
  const outOfDate = publicationOutOfDate(event.current_version, pub);
  const meetupUrl = safeMeetupUrl(pub?.external_url ?? event.meetup_url);
  const known = channel === 'web' || channel === 'meetup';
  const hidden = hiddenBlocksPublish(event.visibility);

  const publishWeb = () => run('web', async () => {
    await setEventPublished(event.id, true);
    return outOfDate || webOn ? 'Published the latest version to the public page.' : 'Public page is on.';
  }, clearConfirm);
  const unpublishWeb = () => run('web-off', async () => {
    await setEventPublished(event.id, false);
    return 'Public page is off. Members can still open this event after they sign in.';
  }, clearConfirm);
  const publishMeetup = (action: 'publish' | 'update') => run(action, async () => {
    const r = await meetupEventAction(event.id, action);
    const done = action === 'publish' ? 'Published to Meetup.' : 'Pushed to Meetup.';
    return [done, ...(r.warnings ?? [])].filter(Boolean).join(' ');
  }, clearConfirm);
  const pullMeetup = () => run('pull', async () => {
    const r = await meetupEventAction(event.id, 'pull');
    const extra = (r.warnings ?? []).filter(Boolean);
    if (r.applied !== true) return ['Meetup refreshed. This club event was not changed.', ...extra].join(' ');
    return ['Pulled from Meetup.', ...extra].join(' ');
  }, clearConfirm);
  const cancelMeetup = () => run('cancel', async () => {
    const r = await meetupEventAction(event.id, 'unpublish');
    return ['Cancelled on Meetup. The club event is still here.', ...(r.warnings ?? [])].filter(Boolean).join(' ');
  }, clearConfirm);

  const canSync = known && channel === 'meetup' && linked && !cancelled;
  const drift = canSync && pub?.snapshot ? meetupSyncRows(event, pub.snapshot) : [];
  const syncTone = drift.length ? 'primary' : 'neutral';
  const openMeetup = channel === 'meetup' && meetupUrl
    ? <Button small variant="neutral" icon="open-outline" title="Open on Meetup" onPress={() => Linking.openURL(meetupUrl)} />
    : null;
  const pushMeetup = canSync && !hidden
    ? <Button small variant={syncTone} icon="cloud-upload-outline" title="Push" accessibilityLabel="Push to Meetup" loading={busy === 'update'} onPress={() => publishMeetup('update')} />
    : null;
  const pullFromMeetup = canSync
    ? confirming === 'pull'
      ? <Button small icon="cloud-download-outline" title="Pull" accessibilityLabel="Pull from Meetup" loading={busy === 'pull'} onPress={pullMeetup} />
      : <Button small variant={syncTone} icon="cloud-download-outline" title="Pull" accessibilityLabel="Pull from Meetup" onPress={() => setConfirming('pull')} />
    : null;
  const bodyText = hidden
    ? 'Hidden events stay off the web directory and Meetup. Share the unlisted link from the event. You can still cancel a Meetup listing that was published before it was hidden.'
    : blurb(channel, { archived: event.archived, on: webOn || meetupOn, outOfDate, linked, cancelled });

  return (
    <PublishRecordPage label={label} subtitle={event.title} backFallback={backFallback}
      status={status} sync={sync}
      fields={[['Last published', fmtDate(pub?.published_at)], ['Event', fmtDate(event.starts_at)]]}
      error={err} note={note} lastError={pub?.last_error ?? null}
      body={bodyText || null}
      versionLine={channel === 'meetup' && linked && !cancelled ? null : publishedVersionLine('club event', event.current_version, pub?.published_version)}
      extras={<>
        {channel === 'web' && webOn ? <PublishLinkLine>{publicEventUrl(event.id)}</PublishLinkLine> : null}
        {channel === 'meetup' && meetupUrl ? <PublishLinkLine>{meetupUrl}</PublishLinkLine> : null}
        {confirming === 'unpublish' ? <PublishConfirmLine>Unpublish? The link will stop showing this event.</PublishConfirmLine> : null}
        {confirming === 'cancel' ? <PublishConfirmLine>Cancel this event on Meetup? The club event stays.</PublishConfirmLine> : null}
        {confirming === 'pull' ? <PublishConfirmLine>Pull replaces this club event with the Meetup listing.</PublishConfirmLine> : null}
      </>}
      actions={<>
        {channel === 'web' && webOn ? <Button small variant="neutral" icon="link-outline" title={copyTitle} onPress={() => { void copy(() => copyPublicEventLink(event.id)); }} /> : null}
        {channel === 'web' && webOn ? <Button small variant="neutral" icon="open-outline" title="View public page" onPress={() => router.push(publicEventPath(event.id))} /> : null}
        {drift.length ? <>{pushMeetup}{pullFromMeetup}{openMeetup}</> : <>{openMeetup}{pushMeetup}{pullFromMeetup}</>}
        {known && channel === 'web' && !hidden && !event.archived && !webOn ? <Button small icon="globe-outline" title="Publish" loading={busy === 'web'} onPress={publishWeb} /> : null}
        {known && channel === 'web' && !hidden && webOn && outOfDate ? <Button small icon="cloud-upload-outline" title="Publish changes" loading={busy === 'web'} onPress={publishWeb} /> : null}
        {known && channel === 'web' && webOn && confirming !== 'unpublish' ? <Button small variant="danger" icon="eye-off-outline" title="Unpublish" onPress={() => setConfirming('unpublish')} /> : null}
        {confirming === 'unpublish' ? <Button small variant="danger" title="Unpublish" loading={busy === 'web-off'} onPress={unpublishWeb} /> : null}
        {known && channel === 'meetup' && !hidden && !linked && !cancelled ? <Button small icon="cloud-upload-outline" title="Publish" loading={busy === 'publish'} onPress={() => publishMeetup('publish')} /> : null}
        {known && channel === 'meetup' && linked && !cancelled && confirming !== 'cancel' ? <Button small variant="danger" icon="close-circle-outline" title="Cancel on Meetup" onPress={() => setConfirming('cancel')} /> : null}
        {confirming === 'cancel' ? <Button small variant="danger" title="Cancel on Meetup" loading={busy === 'cancel'} onPress={cancelMeetup} /> : null}
        {confirming ? <Button small variant="neutral" title="Keep" disabled={!!busy} onPress={clearConfirm} /> : null}
      </>}
      lead={drift.length ? <SectionCard title="Club vs Meetup"><MeetupSyncCompare rows={drift} /></SectionCard> : null}
      showSnapshot={!drift.length}
      snapshot={pub?.snapshot ? <SnapshotBody snapshot={pub.snapshot} /> : null} />
  );
}

function blurb(channel: string, s: { archived: boolean; on: boolean; outOfDate: boolean; linked: boolean; cancelled: boolean }) {
  if (channel === 'web') {
    if (s.archived) return 'Archived events stay off the public page. Restore the event before publishing.';
    if (s.outOfDate) return 'The public page is still the last version you published. Publish changes to send the current club event. Chat and RSVP stay behind sign-in.';
    if (s.on) return 'Anyone with the link can see the title, time, place, description, and cover that you last published. Later edits stay on the club event until you publish changes.';
    return 'The public page is off. Publishing sends this event to gnosis.events. Syncing a public Meetup listing turns this on unless someone unpublished it here.';
  }
  if (channel === 'meetup') {
    if (s.cancelled) return 'This listing was cancelled on Meetup. The club event is still here.';
    if (!s.linked) return 'Publishing creates the event on the Meetup group linked to this club group. Connect your Meetup Pro network on your Profile for that group first. A member link is not enough. Venue text goes into “How to find us”.';
    return '';
  }
  return 'This channel uses the same publish record. Publishing it is not available in this version of the app.';
}
