import React from 'react';
import { Platform, Switch, Text, View } from 'react-native';
import { SectionCard, styles } from './ui';
import { colors, fonts, fs } from '../lib/theme';
import { useBiometric } from '../lib/biometric';

/** Own-profile switch. Hidden on web, where there is no biometric gate. */
export function BiometricSetting() {
  const { enabled, available, unavailableReason, method, busy, error, setEnabled } = useBiometric();
  if (Platform.OS === 'web') return null;
  const help = !available
    ? unavailableReason
    : enabled
      ? `Asks for ${method.name} when you open the app, and after it has been in the background for a minute.`
      : `After you sign in with Google, Apple, or email, ${method.name} can open the app on this phone.`;
  return (
    <SectionCard title="Security">
      <View style={{ flexDirection: 'row', alignItems: 'center', gap: 12 }}>
        <View style={{ flex: 1, minWidth: 0 }}>
          <Text style={styles.rowPrimary}>{method.toggle}</Text>
          {help ? <Text style={[styles.muted, { fontSize: fs(13), marginTop: 4 }]}>{help}</Text> : null}
        </View>
        <Switch
          value={enabled}
          onValueChange={(next) => { void setEnabled(next); }}
          disabled={busy || (!available && !enabled)}
          accessibilityLabel={method.toggle}
          trackColor={{ false: colors.lineStrong, true: colors.navy }}
          thumbColor="#fff"
          ios_backgroundColor={colors.lineStrong}
        />
      </View>
      {error ? <Text style={{ color: colors.danger, fontFamily: fonts.sans, fontSize: fs(13), marginTop: 10 }}>{error}</Text> : null}
    </SectionCard>
  );
}
