/**
 * Public iOS App Store or TestFlight listing, if one is configured.
 * TODO: set EXPO_PUBLIC_IOS_APP_URL to the final https://apps.apple.com/... or
 * https://testflight.apple.com/... URL once that page is live. Until then this
 * stays null and the preview suggest bar stays hidden.
 * There is no Play Store URL: Android must not be sent to a dead listing.
 */
export const IOS_APP_STORE_URL = appleListingUrl(process.env.EXPO_PUBLIC_IOS_APP_URL);

function appleListingUrl(raw: string | undefined): string | null {
  if (!raw?.trim()) return null;
  try {
    const u = new URL(raw.trim());
    if (u.protocol !== 'https:') return null;
    const host = u.hostname.toLowerCase();
    if (host !== 'apps.apple.com' && host !== 'testflight.apple.com') return null;
    return u.toString();
  } catch {
    return null;
  }
}
