// In-app banner for a new direct message, plus a browser notification on web.
// Expo push still fires for installed iOS and Android apps, including while the
// member is online. This banner covers web (no Expo token) and a phone that is
// in the app but not on that thread. The open thread stays quiet.
import React, { useEffect, useRef, useState } from 'react';
import { Platform, Pressable, Text, Vibration, View } from 'react-native';
import { router } from 'expo-router';
import * as Notifications from 'expo-notifications';
import type { RealtimeChannel } from '@supabase/supabase-js';
import { Ionicons } from '@expo/vector-icons';
import { alertPreview, canListenForDmAlerts, shouldAlertForMessage } from '../lib/chat-presence';
import { getProfile, listDms, listMyGroupChats } from '../lib/api';
import { primaryName } from '../lib/names';
import { getActivePushRoom } from '../lib/push';
import { useSession } from '../lib/session';
import { useBiometric } from '../lib/biometric';
import { supabase } from '../lib/supabase';
import { colors, fonts, fs } from '../lib/theme';
import type { Message } from '../lib/types';

type Banner = { key: string; roomId: string; title: string; body: string };

const SEEN_LIMIT = 200;

let askedWebAlerts = false;

export function promptWebMessageAlerts() {
  if (askedWebAlerts || Platform.OS !== 'web' || typeof Notification === 'undefined') return;
  if (Notification.permission !== 'default') return;
  askedWebAlerts = true;
  void Notification.requestPermission().catch(() => {});
}

function notifyBrowser(title: string, body: string, roomId: string) {
  if (Platform.OS !== 'web' || typeof Notification === 'undefined') return;
  if (Notification.permission !== 'granted') return;
  try {
    const n = new Notification(title, { body, tag: `dm:${roomId}` });
    n.onclick = () => {
      window.focus();
      router.push(`/rooms/${roomId}`);
      n.close();
    };
  } catch { /* the in-app banner still shows when the tab is visible */ }
}

export function DmAlertHost() {
  const { userId, demo, session } = useSession();
  const { revealed } = useBiometric();
  const accessToken = session?.access_token ?? null;
  const [banner, setBanner] = useState<Banner | null>(null);
  const seen = useRef(new Set<string>());
  const hideTimer = useRef<ReturnType<typeof setTimeout> | null>(null);

  useEffect(() => {
    // The lock covers the UI, but this host would still vibrate and mount a banner under it.
    if (!revealed || !userId || !accessToken || !canListenForDmAlerts({ demo, userId, accessToken })) return;
    let live = true;
    const dmRooms = new Set<string>();
    const groupRooms = new Set<string>();
    const notPrivate = new Set<string>();
    let chan: RealtimeChannel | null = null;

    const remember = (key: string) => {
      if (seen.current.has(key)) return false;
      seen.current.add(key);
      if (seen.current.size > SEEN_LIMIT) {
        const first = seen.current.values().next().value;
        if (first) seen.current.delete(first);
      }
      return true;
    };

    const present = (next: Banner) => {
      if (!live || !remember(next.key)) return;
      setBanner(next);
      if (Platform.OS !== 'web') Vibration.vibrate(180);
      notifyBrowser(next.title, next.body, next.roomId);
      if (hideTimer.current) clearTimeout(hideTimer.current);
      hideTimer.current = setTimeout(() => {
        setBanner((cur) => (cur?.key === next.key ? null : cur));
      }, 8000);
    };

    const isPrivate = async (roomId: string) => {
      if (dmRooms.has(roomId) || groupRooms.has(roomId)) return { directRoom: dmRooms.has(roomId), memberRoom: groupRooms.has(roomId) };
      if (notPrivate.has(roomId)) return { directRoom: false, memberRoom: false };
      try {
        const [dms, groups] = await Promise.all([listDms(), listMyGroupChats()]);
        if (!live) return { directRoom: false, memberRoom: false };
        dmRooms.clear();
        groupRooms.clear();
        for (const row of dms) dmRooms.add(row.room_id);
        for (const row of groups ?? []) groupRooms.add(row.room_id);
      } catch {
        return { directRoom: false, memberRoom: false };
      }
      const directRoom = dmRooms.has(roomId);
      const memberRoom = groupRooms.has(roomId);
      if (!directRoom && !memberRoom) notPrivate.add(roomId);
      return { directRoom, memberRoom };
    };

    const onMessage = async (row: Partial<Message> | null) => {
      const roomId = typeof row?.room_id === 'string' ? row.room_id : '';
      const senderId = typeof row?.user_id === 'string' ? row.user_id : '';
      const id = row?.id;
      if (!roomId || !senderId || (typeof id !== 'number' && typeof id !== 'string')) return;
      const privacy = await isPrivate(roomId);
      if (!live) return;
      if (!shouldAlertForMessage({
        senderId,
        selfId: userId,
        roomId,
        activeRoomId: getActivePushRoom(),
        directRoom: privacy.directRoom,
        memberRoom: privacy.memberRoom,
        removed: !!row?.deleted_at,
      })) return;
      let title = 'New message';
      try {
        const profile = await getProfile(senderId);
        if (profile) title = primaryName(profile);
      } catch { /* keep the generic title */ }
      if (!live) return;
      if (getActivePushRoom() === roomId) return;
      present({
        key: String(id),
        roomId,
        title,
        body: alertPreview(typeof row?.body === 'string' ? row.body : ''),
      });
    };

    // Set the session on the socket before joining. An anonymous join is
    // filtered by RLS and stays quiet for the rest of the connection.
    const join = () => {
      if (!live) return;
      chan = supabase.channel(`dm-alerts:${userId}`)
        .on('postgres_changes', { event: 'INSERT', schema: 'public', table: 'messages' }, (payload) => {
          void onMessage(payload.new as Partial<Message>);
        })
        .subscribe();
    };
    void Promise.resolve(supabase.realtime.setAuth(accessToken)).then(join).catch(join);

    let pushSub: { remove: () => void } | null = null;
    if (Platform.OS !== 'web') {
      // Foreground Expo pushes arrive here as well as through the system banner.
      // Only direct messages. The message id dedupes with the Realtime insert.
      pushSub = Notifications.addNotificationReceivedListener((notification) => {
        const data = notification.request.content.data as Record<string, unknown> | undefined;
        const roomId = typeof data?.roomId === 'string' ? data.roomId : '';
        const messageId = typeof data?.messageId === 'string' ? data.messageId : '';
        if (!roomId || !messageId) return;
        void (async () => {
          const privacy = await isPrivate(roomId);
          if (!live || (!privacy.directRoom && !privacy.memberRoom) || getActivePushRoom() === roomId) return;
          present({
            key: messageId,
            roomId,
            title: notification.request.content.title || 'New message',
            body: alertPreview(notification.request.content.body || ''),
          });
        })();
      });
    }

    return () => {
      live = false;
      if (hideTimer.current) clearTimeout(hideTimer.current);
      pushSub?.remove();
      if (chan) supabase.removeChannel(chan);
    };
  }, [userId, demo, accessToken, revealed]);

  if (!banner) return null;
  const open = () => {
    const roomId = banner.roomId;
    setBanner(null);
    router.push(`/rooms/${roomId}`);
  };
  return (
    <View pointerEvents="box-none" style={{ position: 'absolute', top: 8, left: 0, right: 0, zIndex: 40, alignItems: 'center', paddingHorizontal: 12 }}>
      <View
        accessibilityLiveRegion="polite"
        style={{
          maxWidth: 520, width: '100%', backgroundColor: colors.navy, borderRadius: 10,
          paddingVertical: 12, paddingHorizontal: 14, flexDirection: 'row', gap: 10, alignItems: 'center',
          shadowColor: '#000', shadowOpacity: 0.2, shadowRadius: 12, shadowOffset: { width: 0, height: 6 }, elevation: 8,
        }}
      >
        <Pressable onPress={open} accessibilityRole="button" accessibilityLabel={`New message from ${banner.title}. Open chat.`} style={{ flex: 1, minWidth: 0, flexDirection: 'row', gap: 10, alignItems: 'center' }}>
          <Ionicons name="chatbubble" size={18} color="#fff" />
          <View style={{ flex: 1, minWidth: 0 }}>
            <Text style={{ fontFamily: fonts.sansMedium, fontSize: fs(12), color: '#d5deee' }}>New message</Text>
            <Text style={{ fontFamily: fonts.sansBold, fontSize: fs(15), color: '#fff' }} numberOfLines={1}>{banner.title}</Text>
            {banner.body ? <Text style={{ fontFamily: fonts.sans, fontSize: fs(13), color: '#e7edf7', marginTop: 2 }} numberOfLines={2}>{banner.body}</Text> : null}
          </View>
        </Pressable>
        <Pressable onPress={() => setBanner(null)} hitSlop={10} accessibilityRole="button" accessibilityLabel="Dismiss message alert">
          <Ionicons name="close" size={18} color="#fff" />
        </Pressable>
      </View>
    </View>
  );
}
