// Sponsors related list on a club group, and the public page block.
// Title, body, image, and link come from the row. No sample copy.
import React, { useCallback, useState } from 'react';
import { Image, Linking, Platform, Pressable, Text, View } from 'react-native';
import { useFocusEffect } from 'expo-router';
import { Button, EmptyState, ErrorText, Field, ListRow, ListView, SectionCard, styles } from './ui';
import { deleteGroupSponsor, listGroupSponsors, moveGroupSponsor, saveGroupSponsor } from '../lib/groups';
import { safeSponsorUrl, type GroupSponsorDraft } from '../lib/public-group';
import { colors, fonts, fs } from '../lib/theme';
import type { GroupSponsor, PublicGroupSponsor } from '../lib/types';

const blank: GroupSponsorDraft = { title: '', body: '', image_url: '', link_url: '' };
const toDraft = (row: GroupSponsor): GroupSponsorDraft => ({
  title: row.title, body: row.body, image_url: row.image_url ?? '', link_url: row.link_url ?? '',
});

function openSponsor(url: string) {
  if (Platform.OS === 'web' && typeof window !== 'undefined') {
    window.open(url, '_blank', 'noopener,noreferrer');
    return;
  }
  Linking.openURL(url).catch(() => {});
}

/** God-mode related list: add, edit, reorder, remove. */
export function GroupSponsors({ groupId }: { groupId: string }) {
  const [rows, setRows] = useState<GroupSponsor[] | null>(null);
  const [err, setErr] = useState<string | null>(null);
  const [draft, setDraft] = useState<GroupSponsorDraft | null>(null);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [busy, setBusy] = useState<string | null>(null);
  const load = useCallback(() => {
    return listGroupSponsors(groupId).then((list) => { setRows(list); setErr(null); }).catch((e: { message?: string }) => setErr(e.message ?? 'Could not load sponsors.'));
  }, [groupId]);
  useFocusEffect(useCallback(() => { load(); }, [load]));

  const run = async (label: string, fn: () => Promise<void>) => {
    setBusy(label); setErr(null);
    try { await fn(); await load(); } catch (e: any) { setErr(e.message); } finally { setBusy(null); }
  };
  const startAdd = () => { setEditingId(null); setDraft(blank); };
  const startEdit = (row: GroupSponsor) => { setEditingId(row.id); setDraft(toDraft(row)); };
  const set = (key: keyof GroupSponsorDraft) => (value: string) => setDraft((cur) => (cur ? { ...cur, [key]: value } : cur));
  const save = () => {
    if (!draft) return;
    run('save', async () => {
      await saveGroupSponsor(groupId, draft, editingId ?? undefined);
      setDraft(null); setEditingId(null);
    });
  };
  const remove = (id: string) => run(`delete:${id}`, async () => {
    await deleteGroupSponsor(groupId, id);
    if (editingId === id) { setDraft(null); setEditingId(null); }
  });
  const move = (id: string, direction: -1 | 1) => run(`move:${id}`, () => moveGroupSponsor(groupId, id, direction));
  const preview = draft ? safeSponsorUrl(draft.image_url) : null;

  return (
    <View>
      <ErrorText>{err}</ErrorText>
      <ListView title="Sponsors" count={rows?.length} loading={!rows && !err}
        empty={err || draft ? undefined : <EmptyState icon="image-outline" title="No sponsors" action={<Button small icon="add" title="Add" onPress={startAdd} />} />}
        footer={draft ? (
          <View style={{ padding: 16 }}>
            <Field label="Title" value={draft.title} onChangeText={set('title')} maxLength={160} />
            <Field label="Body" value={draft.body} onChangeText={set('body')} multiline maxLength={2000} />
            <Field label="Image URL" help="https link." value={draft.image_url} onChangeText={set('image_url')} autoCapitalize="none" autoCorrect={false} maxLength={2000} />
            {preview ? <Image source={{ uri: preview }} accessibilityIgnoresInvertColors resizeMode="contain" style={{ width: 160, height: 64, marginBottom: 14, backgroundColor: colors.headerBg, borderRadius: 6 }} /> : null}
            <Field label="Link" help="https link." value={draft.link_url} onChangeText={set('link_url')} autoCapitalize="none" autoCorrect={false} maxLength={2000} />
            <View style={{ flexDirection: 'row', gap: 8, flexWrap: 'wrap' }}>
              <Button title={editingId ? 'Save' : 'Add'} onPress={save} loading={busy === 'save'} />
              <Button variant="neutral" title="Cancel" onPress={() => { setDraft(null); setEditingId(null); }} />
            </View>
          </View>
        ) : rows && rows.length > 0 ? (
          <View style={{ paddingHorizontal: 16, paddingVertical: 12 }}>
            <Button small icon="add" title="Add" onPress={startAdd} />
          </View>
        ) : null}>
        {rows?.map((row, index) => (
          <ListRow key={row.id}>
            <View style={{ flexDirection: 'row', alignItems: 'center', gap: 8, flexWrap: 'wrap' }}>
              <View style={{ flexGrow: 1, flexShrink: 1, flexBasis: 160, minWidth: 120 }}>
                <Text style={styles.rowPrimary} numberOfLines={1}>{row.title}</Text>
                {row.body ? <Text style={[styles.muted, { fontSize: fs(12) }]} numberOfLines={1}>{row.body}</Text> : null}
              </View>
              <View style={{ flexDirection: 'row', gap: 6, flexWrap: 'wrap' }}>
                <Button small variant="neutral" title="Up" disabled={index === 0 || !!busy} onPress={() => move(row.id, -1)} />
                <Button small variant="neutral" title="Down" disabled={!rows || index === rows.length - 1 || !!busy} onPress={() => move(row.id, 1)} />
                <Button small variant="neutral" title="Edit" disabled={!!busy} onPress={() => startEdit(row)} />
                <Button small variant="danger" title="Delete" loading={busy === `delete:${row.id}`} onPress={() => remove(row.id)} />
              </View>
            </View>
          </ListRow>
        ))}
      </ListView>
    </View>
  );
}

function SponsorCard({ sponsor, href }: { sponsor: PublicGroupSponsor; href: string | null }) {
  const image = safeSponsorUrl(sponsor.image_url);
  const body = (
    <View style={{ flexDirection: 'row', alignItems: 'flex-start', gap: 10 }}>
      {image ? (
        <Image source={{ uri: image }} accessibilityIgnoresInvertColors resizeMode="contain"
          style={{ width: 72, height: 54, borderRadius: 6, backgroundColor: colors.headerBg }} />
      ) : null}
      <View style={{ flex: 1, minWidth: 0, gap: 2 }}>
        <Text style={{ fontFamily: fonts.sansBold, fontSize: fs(14), lineHeight: fs(18), color: colors.navyDark }}>{sponsor.title}</Text>
        {sponsor.body ? <Text style={[styles.muted, { fontSize: fs(13), lineHeight: fs(18) }]}>{sponsor.body}</Text> : null}
      </View>
    </View>
  );
  if (!href) return body;
  return (
    <Pressable accessibilityRole="link" accessibilityLabel={sponsor.title} onPress={() => openSponsor(href)}
      style={({ pressed }) => [{ opacity: pressed ? 0.75 : 1 }]}>
      {body}
    </Pressable>
  );
}

/** Public group sidebar. Omitted when the group has no sponsors. */
export function PublicGroupSponsors({ sponsors }: { sponsors: PublicGroupSponsor[] }) {
  const shown = sponsors.filter((row) => row.title.trim());
  if (!shown.length) return null;
  return (
    <SectionCard title="Sponsors">
      <View style={{ gap: 14 }}>
        {shown.map((sponsor) => (
          <SponsorCard key={sponsor.id} sponsor={sponsor} href={safeSponsorUrl(sponsor.link_url)} />
        ))}
      </View>
    </SectionCard>
  );
}
